// ОТКАЗ ЧТЕНИЯ РЕЕСТРА НЕ ДОЛЖЕН РОНЯТЬ ФЛОУ ЦЕЛИКОМ.
//
// Живой прогон 2026-08-31: GitLab ответил 404 на `kb/index.md`, и ядро
// умерло на ПЕРВОМ узле. Ни ответа, ни разбора, ни строки джуну — в канале
// это выглядит как «бот промолчал», то есть неотличимо от «ответа в базе
// нет». Ровно тот тихий отказ, от которого защищена вся остальная
// конструкция: у `Read article` `onError: continueRegularOutput` стоит
// с самого начала, а у чтения реестра — самого важного чтения из всех —
// не стояло ничего.
//
// Теперь узел пропускает отказ дальше, а разбор превращает его в пустой
// реестр плюс НАЗВАННУЮ причину. Ответа по существу не будет всё равно:
// без реестра роутер не выберет ни статьи, ни домена. Но джун получит
// сообщение с конкретным путём и проектом, а не тишину.
const err = $json.error || $json.message ||
  (typeof $json.content !== 'string' ? 'узел чтения реестра не вернул файл' : '');
if (err || typeof $json.content !== 'string') {
  return [{ json: {
    text: '', full: '', saved_chars: 0,
    registry_error: 'реестр базы знаний не прочитан: ' + String(err),
  } }];
}

const full = Buffer.from($json.content, 'base64').toString('utf8');

// Только markdown-таблицы и их заголовки: «## Домены», «## Сущности» и строки,
// начинающиеся с «|». Комментарии <!-- --> и пояснительная проза отбрасываются.
//
// Таблицы, по которым решение принимает КОД, роутеру не нужны вовсе, и он
// за них платит токенами на каждом обращении. «Самостоятельные выгрузки» —
// это отчёты-трансформеры, их находит «Plan» по ключевым словам; «Маршруты» —
// эксперты по доменным темам, их находит он же. Модели по ним решать нечего:
// увидев их, она в лучшем случае повторит работу кода, в худшем — подставит
// id отчёта в plan.articles как путь к статье.
//
// Отбрасываются ПО ЗАГОЛОВКУ, а не по номеру секции: порядок разделов
// в index.md может поменяться, смысл заголовка — нет. Неизвестный заголовок
// остаётся: реестр растёт, и новая таблица должна доезжать до роутера
// по умолчанию, а не пропадать молча.
const CODE_ONLY = ['## Самостоятельные выгрузки', '## Маршруты'];
const keep = [];
let skip = false;
for (const raw of full.split('\n')) {
  const l = raw.trim();
  if (l.startsWith('##')) {
    skip = CODE_ONLY.includes(l);
    if (!skip) keep.push(l);
    continue;
  }
  if (skip) continue;
  if (l.startsWith('|')) { keep.push(l); continue; }
}
const compact = keep.join('\n');

// Проекция не должна оказаться пустой: формат index.md мог измениться.
// Пустой реестр — это молча неработающий роутер, поэтому в этом случае
// отдаём полный текст: дороже, но работает.
const text = compact.includes('|') ? compact : full;

// Файл прочитан, но пустой — тоже отказ, и молчать о нём нельзя: роутер
// получит пустой реестр и не выберет ничего, а по виду прогона это
// неотличимо от «в базе нет ответа».
if (!full.trim()) {
  return [{ json: {
    text: '', full: '', saved_chars: 0,
    registry_error: 'реестр базы знаний прочитан, но пуст',
  } }];
}

return [{ json: { text, full, saved_chars: full.length - text.length,
                  registry_error: '' } }];

// Разбор вывода роутера и построение плана чтения.
//
// Роутер отдаёт JSON. Модель иногда оборачивает его в ```json-заборы или
// добавляет слово перед ним, поэтому объект вырезается по первой «{» и
// последней «}», а не парсится целиком. Сбой разбора не роняет флоу: план
// остаётся пустым, автор получит материалы без статей и честно скажет, что
// в базе ответа нет. Молча превратить сбой в «бот не знает» нельзя — поэтому
// причина уходит в router_error и попадает в служебный блок лога.
const rawOut = String($json.output ?? $json.text ?? '').trim();

let plan = { domains: [], articles: [], dd: [], no_question: false };
let routerError = '';

// Предел числа объектов DD. Каждый объект — от одного до тринадцати HTTP-запросов
// внутри DD Lookup (карточка, список колонок, до 12 карточек колонок), поэтому
// четыре объекта это уже до 52 запросов. Обрезанное называется, а не режется
// молча — то же правило, что для статей.
const MAX_DD = 4;

try {
  const a = rawOut.indexOf('{');
  const b = rawOut.lastIndexOf('}');
  if (a === -1 || b <= a) throw new Error('в выводе роутера нет JSON-объекта');
  const got = JSON.parse(rawOut.slice(a, b + 1));
  plan.domains = Array.isArray(got.domains) ? got.domains.map(String) : [];
  plan.articles = Array.isArray(got.articles) ? got.articles.map(String) : [];
  plan.no_question = got.no_question === true;

  // Объекты DD. Основная форма — массив { urn, hint }.
  //
  // Скалярная форма { dd_urn, field_hint } тоже принимается: модель, увидев
  // старый пример или сбившись с формата, вернёт именно её, и терять из-за
  // этого метаданные целиком нельзя. Пустой инвентарь агент читает как
  // «полей нет» — ошибка тихая и потому дорогая.
  const rawDD = Array.isArray(got.dd)
    ? got.dd
    : typeof got.dd_urn === 'string' && got.dd_urn.trim()
      ? [{ urn: got.dd_urn, hint: got.field_hint }]
      : [];

  // Повтор URN СКЛЕИВАЕТ иглы, а не выбрасывает вторую.
  //
  // Раньше второй элемент с тем же URN отбрасывался целиком — «один объект
  // дважды это лишние запросы». Запросы и правда лишние, а вот игла нет:
  // вопрос «какое поле хранит логин и есть ли рабочая почта» — это один
  // объект и ДВА понятия. 2026-08-26 бот на нём уверенно ответил, что рабочей
  // почты в витрине нет; поля искали по одной игле «логин», а почту
  // не искали вовсе. Поле в витрине есть.
  // Объект по-прежнему один, запрос один — фильтр стал списком.
  const byUrnHints = new Map();
  for (const it of rawDD) {
    // Элемент может прийти и просто строкой-урном, без обёртки.
    const urn = String((it && typeof it === 'object' ? it.urn : it) ?? '').trim();
    if (!urn || urn === '—' || !urn.startsWith('urn:')) continue;
    const hint = String((it && typeof it === 'object' ? it.hint : '') ?? '').trim();
    if (!byUrnHints.has(urn)) byUrnHints.set(urn, []);
    const hints = byUrnHints.get(urn);
    // Пустая игла среди непустых бессмысленна: пустой фильтр означает
    // «отдай весь инвентарь», и рядом с конкретным словом он только
    // сбивает режим поиска. Дубли слов тоже ни к чему.
    if (hint && !hints.includes(hint)) hints.push(hint);
  }
  // ЗНАЧЕНИЙ ФИЛЬТРОВ РОУТЕР БОЛЬШЕ НЕ ВЫДЕЛЯЕТ, и это следствие переноса
  // проверки за автора. Раньше он возвращал values рядом с hint, и по ним
  // каталог ходил в данные ещё до того, как хоть что-то прочитано. Выбор
  // «в каком поле искать слово заказчика» делается по правилу из статьи,
  // а у роутера статьи нет — он раз за разом отправлял искать «юнит»
  // в юридической структуре вместо управленческой.
  // Теперь пары «поле = слово» называет автор, у которого есть и статья,
  // и рецепт, и инвентарь разом. Оставлять сбор values «на всякий случай»
  // нельзя: это код, который не работает и выглядит рабочим, — ровно то,
  // из-за чего в проекте заведён отдельный запрет.
  // Игл на объект. Раньше стояло 4 «чтобы фильтр не размывался», но игла —
  // это одно слово, все они склеиваются в ОДИН запрос, и промах по любой
  // из них стоит ровно того же, что раньше стоил выброшенный дубль URN:
  // понятие не искали вовсе, а ответ про него выглядит проверенным.
  // Восемь — предел вопроса, а не предел кода: в живом трафике больше
  // четырёх понятий в одном вопросе не встречалось ни разу.
  const MAX_HINTS = 8;
  for (const [urn, hints] of byUrnHints) {
    plan.dd.push({ urn, hint: hints.slice(0, MAX_HINTS).join(', ') });
  }
} catch (e) {
  routerError = `не удалось разобрать план роутера: ${e.message}`;
}

// let, а не const: ниже сюда же дописывается то, что срезал повторный
// потолок после добора инвентаря прочитанных витрин.
const ddDropped = plan.dd.slice(MAX_DD).map((d) => d.urn);
plan.dd = plan.dd.slice(0, MAX_DD);

// Таблица «Домены» из реестра: домен → мастер-сущности. Мастерство — свойство
// пары «домен + сущность», поэтому берётся именно из этой таблицы, а не из
// строки сущности.
// Берём ПОЛНЫЙ текст, а не проекцию для промпта: разбор мастеров не должен
// зависеть от того, что и как проекция отфильтровала.
const reg = $('Decode registry').first().json;
const registry = String(reg.full ?? reg.text ?? '');
// Реестр не прочитался: без него роутер не выберет ни статьи, ни домена,
// и мастера не доберутся. Признак едет дальше, чтобы отказ был НАЗВАН,
// а не выглядел как «в базе нет ответа».
const registryError = String(reg.registry_error || '');

// Секция читается до СЛЕДУЮЩЕГО заголовка «## », какой бы он ни был, а не до
// заранее вписанного соседа. Раньше границей служило имя следующей секции —
// и это молча ломалось дважды: сначала «Самостоятельные выгрузки» читались
// до конца файла и подхватывали строки новой таблицы «Маршруты» (id маршрута
// становился id отчёта), потом границы пришлось вписывать парами. Любая новая
// секция реестра или смена их порядка снова разъезжались бы с кодом — притом
// беззвучно: чужие строки разбираются как свои, формат колонок другой,
// а на выходе просто неверные данные. Реестр правят чаще, чем сборщик.
function rows(section) {
  const i = registry.indexOf(section);
  if (i === -1) return [];
  const after = registry.indexOf('\n## ', i + section.length);
  const chunk = registry.slice(i, after === -1 ? registry.length : after);
  return chunk
    .split('\n')
    .filter((l) => l.trim().startsWith('|'))
    .map((l) => l.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((c) => c.trim()))
    .filter((c) =>
      c.length > 1 && !/^-+$/.test(c[0]) &&
      c[0] !== 'домен' && c[0] !== 'id' && c[0] !== 'id отчёта' &&
      c[0] !== 'маршрут',
    );
}

const masters = new Map();          // домен → [id мастеров]
for (const c of rows('## Домены')) {
  masters.set(c[0], String(c[2] || '').split(',').map((s) => s.trim()).filter(Boolean));
}

// Граница секции — следующий заголовок «## » (см. rows выше): без неё таблица
// «Самостоятельные выгрузки» со своим форматом колонок (id отчёта, ключевые
// слова) подмешалась бы в разбор путей и dd_urn сущностей.
const byId = new Map();             // id сущности → путь к статье
const byUrn = new Map();            // id сущности → dd_urn (для отчётов без статьи)
const byTitle = new Map();          // id сущности → название, для сообщения автору
// Путь статьи → сама витрина. Нужна, чтобы код мог добрать инвентарь полей
// по прочитанной статье: живой прогон 2026-08-27 показал, что статью про
// витрину автор читает, а состав её полей — нет, и разницы между этим
// не делает ни он, ни код (см. ниже, «инвентарь витрин добирается кодом»).
const tableByPath = new Map();      // путь → {id, urn, title}
for (const c of rows('## Сущности')) {
  const path = String(c[4] || '').trim();
  if (path && path !== '—') byId.set(c[0], path);
  const urn = String(c[5] || '').trim();
  if (urn && urn !== '—') byUrn.set(c[0], urn);
  byTitle.set(c[0], String(c[3] || '').trim());
  if (path && path !== '—' && urn && urn !== '—' && c[1] === 'table') {
    tableByPath.set(path, { id: c[0], urn, title: String(c[3] || '').trim() });
  }
}

// Мастера выбранных доменов — впереди остальных статей: автор читает материалы
// сверху вниз, и основание должно идти раньше частностей.
const ordered = [];
const seen = new Set();
const add = (p) => {
  if (p && p !== '—' && !seen.has(p)) { seen.add(p); ordered.push(p); }
};

// ------------------------------------------------ обязательные статьи выгрузки
//
// Тему обращения проставил ЧЕЛОВЕК в intake-форме — самый надёжный сигнал
// из всех доступных, надёжнее вывода модели. Поэтому для выгрузок плейбук
// и развилка «сотрудник или позиция» добираются КОДОМ, а не просьбой
// в промпте роутера («Запрос на выгрузку — всегда добавляй export-playbook»):
// живой прогон уже показывал, что словесные обязательства модель не держит,
// и ровно по этой причине мастеров домена добирает код.
//
// Цена пропуска здесь высокая и незаметная: без плейбука автор отвечает
// по существу вместо согласования, а без rc-structure-choice не задаёт
// вопрос про «сотрудники или все оформления» — и выгрузка выходит
// правдоподобной и неверной.
//
// Путь плейбука записан строкой: kb/process/ в таблице «Сущности» реестра
// не зарегистрирован вовсе, резолвить его по id неоткуда. Появится строка —
// заменить на резолв по id, как у развилки ниже. Если файла нет, «Build
// materials» скажет об этом вслух: реестр ссылается на несуществующий файл.
const trig0 = $('When called by adapter').first().json ?? {};
const question0 = String(trig0.question ?? '');

// Тема обращения. Основной источник — поле формы: его проставил человек.
// Но форму разбирает guard АДАПТЕРА, и знает её только канал: «Adapter Chat»
// передаёт topic_kind пустой строкой, а в личке формы нет вовсе. Поэтому тема
// восстанавливается ещё и из шапки самого обращения — в чат пост вставляют
// целиком, вместе с «Cross Data | Выгрузка данных от пользователя @X».
const head0 = question0.split('\n')[0].replace(/^[\s>*_#`~]+/, '').trim();
const topicKind = String(trig0.topic_kind ?? '') ||
  (/^cross data\s*\|/i.test(head0) ? head0 : '');

// Признак выгрузки считается по ТЕМЕ — своей или восстановленной из шапки,
// но не по всему тексту обращения. Слово «выгруз» встречается сплошь и в тех
// обращениях, где тему человек выбрал другую: «необходимо завести запрос
// на выгрузку» стоит в половине ответов по теме «Мне только спросить».
// Признак по тексту включал бы там весь режим: две лишние статьи, правила
// оформления в промпте автора и требование блока ТЗ. Тема остаётся сигналом
// человека, как и было.
//
// Живой прогон из чата 2026-08-17 показал, зачем здесь восстановление темы.
// Обращение было ровно про «Детальные списки» (нужны логины сотрудников
// юнита), а отчёт бот не предложил: topic_kind в чате пуст, isExport был
// false, и блок самообслуживания ниже не запускался вовсе. При этом «Build
// materials» режим выгрузки ВОССТАНАВЛИВАЛ по плейбуку среди прочитанного,
// и на выходе ядра стояло is_export: true — то есть по выходу отказ
// неотличим от нормальной работы. Асимметрия «у режима фолбэк есть,
// у поиска отчёта нет» и была причиной.
//
// Порядок files при этом остаётся диагностикой: при isExport плейбук
// и развилка идут ПЕРВЫМИ, а если плейбук пришёл последним — значит его
// выбрал роутер, а режим был выключен.
// Ссылка на отчёт: из поля формы, а если формы нет — из текста обращения.
// В чат и в личку пост вставляют целиком, вместе со ссылкой на дашборд.
const reportUrlFound = String(trig0.report_url ?? '').trim() ||
  (question0.match(/https?:\/\/[^\s)»"']*(?:dashboard|superset|proteus)[^\s)»"']*/i) || [''])[0];

const isExport = /выгруз/i.test(topicKind);
const EXPORT_PATHS = ['kb/process/export-playbook.md'];
const EXPORT_IDS = ['rc-structure-choice'];

// Обращение про доступ. Тот же приём, что и с плейбуком выгрузки: статьи
// из kb/process/ НЕ заведены сущностями в реестре — у них нет ни dd_urn,
// ни домена, они описывают процесс, а не данные. Роутер их поэтому никогда
// не выберет, и добирать их приходится кодом по теме формы.
//
// Тема «Нет доступа к отчету» — одна из четырёх, по которым приходят
// обращения, и ответ на неё в базе должен быть. Пока routing.md со статусом
// draft и плейсхолдерами ‹…›, бот честно скажет, что значение не заполнено,
// а «Задача для базы» назовёт, что именно дописать. Это лучше, чем «в базе
// ответа нет»: видно, где ответ должен лежать.
//
// Здесь признак считается ТОЛЬКО по теме, без запасного признака по тексту —
// в отличие от выгрузки. Слово «доступ» стоит в самой форме выгрузки
// («Перечисли логины сотрудников, кому необходимо дать доступ к выгрузке»),
// и признак по тексту тянул бы статью маршрутизации в каждое обращение
// про выгрузку. Тема, восстановленная из шапки, работает и в чате.
const isAccess = /доступ/i.test(topicKind);
const ACCESS_PATHS = ['kb/process/routing.md'];

// Просят помочь НАПИСАТЬ ЗАПРОС — это вопрос аналитика, а не заявка на файл.
//
// Живой прогон 2026-08-27: «Можешь подсказать, как написать select, чтобы
// выгрузить сотрудника, его управленческий юнит и его юнит из функциональной
// структуры?» — и бот выдал согласование состава полей, три уточняющих
// вопроса и ТЗ для аналитика. То есть на просьбу написать запрос ответил
// «давайте сначала согласуем, что выгружаем», а SQL не написал: в режиме
// выгрузки он прямо запрещён.
//
// Режим включился не по теме — формы в чате нет вовсе, — а фолбэком
// «среди прочитанного есть плейбук выгрузки». Здесь и лежит развилка:
// тема из формы это ФАКТ, её проставил человек; восстановление по плейбуку
// это ДОГАДКА. Признак «просят запрос» перебивает догадку и не трогает факт,
// поэтому настоящая выгрузка со словом «select» в тексте режим не потеряет.
//
// Слово «выгруз» намеренно НЕ отменяет признак: «как написать select, чтобы
// выгрузить» — это ровно тот случай, ради которого всё и делается.
const QUERY_RE = /\b(?:select|sql|join)\b|как\s+(?:написать|составить|собрать|посчитать|вытащить|достать)|подскажи(?:те)?\s+(?:запрос|как)|какой\s+(?:джойн|join|запрос)|напиш(?:и|ите)\s+(?:запрос|select|sql)/i;
const isQueryHelp = QUERY_RE.test(question0);
// Статьи kb/process/ роутер не выбирает никогда — их нет в реестре, — поэтому
// конвенции запросов добираются кодом, как плейбук и маршрутизация. До этой
// правки sql-conventions.md не добирал НИКТО: файл лежал в базе и не доезжал
// до автора ни разу, то есть на вопрос про запрос у него не было ни одной
// статьи про то, как этот запрос положено писать.
const QUERY_PATHS = ['kb/process/sql-conventions.md'];

// ВОПРОС ПРО ПОДРАЗДЕЛЕНИЕ — рецепт поиска уровня и ключа добирается КОДОМ.
//
// Заказчик называет юнит словами («в юните Human Capital Origination»),
// а в витрине это ключ на одном из десяти уровней иерархии, и поля разные
// для каждого N. Угадать уровень нельзя — нужен двухшаговый алгоритм
// из rc-find-unit-level: сначала уровень и ключ, потом выгрузка.
//
// Роутер этот рецепт выбирает не всегда: вопрос выглядит как «сколько
// аналитиков», и подразделение в нём — одно слово из пяти. Живой прогон
// 2026-08-28 показал, что без рецепта автор либо угадывает уровень, либо
// честно пишет, что готового ключа нет. Поэтому решение переезжает в код —
// как мастера домена и плейбук выгрузки.
//
// Признак по ТЕКСТУ, а не по теме формы: подразделение называют и в вопросе,
// и в заявке на выгрузку, и в личке, где формы нет вовсе. Ложное срабатывание
// здесь дёшево — одна статья в материалах, — а пропуск дорог: без рецепта
// ответ либо неверен, либо неполон.
// Без \b рядом с кириллицей: в JS границы слова определены по ASCII,
// и `\bюнит` не совпадает НИКОГДА — пятый случай этого класса в проекте.
// Ловится тестом 43, но написать его заново оказалось проще, чем не написать.
const UNIT_RE = /юнит|подразделен|департамент|дирекци|\bunit\b|lvl\d/i;
const isUnitQuestion = UNIT_RE.test(question0);

// ССЫЛКА НА ЮНИТ — ОТДЕЛЬНЫЙ ПРИЗНАК, И ОН ТОЧНЫЙ.
//
// Заказчик часто присылает не название подразделения, а ссылку:
//   my.tbank.ru/structure/resource/units/<uuid>   — управленческая структура
//   my.tbank.ru/product-catalog/product/<uuid>    — Каталог продуктов
// В ссылке стоит `id` юнита, а в основных витринах его НЕТ — там только `rk`.
// Перевод делается через справочник (dds.management_unit / dds.functional_unit),
// и без него ссылка бесполезна.
//
// Живой прогон 2026-08-31: бот искал uuid из ссылки среди значений
// mapped_management_unit_nm и lvl5_mapped_management_unit_rk, не нашёл —
// и написал заказчику, что юнит «не обнаружился ни по названию,
// ни по идентификатору», предложив самому сказать, где его искать.
// Ни в одном из этих полей его и не могло быть.
//
// Признак ТОЧНЫЙ, в отличие от UNIT_RE выше: это конкретный вид ссылки,
// ложных срабатываний у него нет. Поэтому по нему добирается не только
// рецепт, но и инвентарь обоих справочников — имена полей `*_unit_id`
// и `*_unit_rk` автор иначе не увидит и подставит правдоподобные.
const UNIT_LINK_RE =
  /my\.tbank\.ru\/(structure\/resource\/units|product-catalog\/product)\/([0-9a-f-]{8,})/i;
const unitLink = UNIT_LINK_RE.exec(question0);
const isUnitLink = Boolean(unitLink);
// Какая структура — видно по виду ссылки, угадывать не нужно.
const unitLinkKind = !unitLink ? ''
  : (/structure\/resource\/units/i.test(unitLink[1]) ? 'management' : 'functional');
const unitLinkId = unitLink ? unitLink[2] : '';
const UNIT_IDS = ['rc-find-unit-level'];

const addedExport = [];
if (isExport) {
  // Впереди мастеров домена: для выгрузки согласование и развилка витрины —
  // это основание, а численность и метрики — частности.
  for (const p of EXPORT_PATHS) { if (!seen.has(p)) addedExport.push(p); add(p); }
  for (const id of EXPORT_IDS) {
    const p = byId.get(id);
    if (p && !seen.has(p)) addedExport.push(p);
    add(p);
  }
}

const addedAccess = [];
if (isAccess) {
  for (const p of ACCESS_PATHS) { if (!seen.has(p)) addedAccess.push(p); add(p); }
}

const addedQuery = [];
if (isQueryHelp) {
  for (const p of QUERY_PATHS) { if (!seen.has(p)) addedQuery.push(p); add(p); }
}

// Рецепт поиска юнита — по id из реестра, а не по вписанному пути: путь
// живёт в одном месте, в реестре, и переименование статьи не должно
// молча отключать правило.
// АКТИВНАЯ ЧИСЛЕННОСТЬ — УМОЛЧАНИЕ ДЛЯ ЛЮБОГО ЗАПРОСА ПО СОТРУДНИКАМ.
//
// Витрина сотрудников хранит и уволенных. Запрос без фильтра активности
// выполнится, вернёт правдоподобное число и будет молча завышен — заказчик
// не узнает об этом никогда. Поэтому правило звучит как умолчание: если
// человек прямо не просит всех, включая уволенных, фильтр обязателен.
//
// Само условие здесь НЕ ПОВТОРЯЕТСЯ — ни кодом, ни комментарием: формулы
// метрик живут в git, и вторая копия разъезжается молча. Код отвечает
// только за то, чтобы статья ДОЕХАЛА до автора на каждом запросе, где
// пишется SQL или собирается выгрузка.
//
// ГЕЙТ СНЯТ 01.09 — по тому же разбору, что и у словаря. Правило названо
// «УМОЛЧАНИЕ ДЛЯ ЛЮБОГО ЗАПРОСА ПО СОТРУДНИКАМ», а стояло на гейте выгрузки:
// в личке не срабатывало вовсе. Между тем именно в личке ответ уходит
// заказчику без джуна между, и завышенная численность из-за пропущенного
// фильтра активности там дороже всего.
const HEADCOUNT_IDS = ['m-active-headcount'];
const addedHeadcount = [];
if (!plan.no_question) {
  for (const id of HEADCOUNT_IDS) {
    const pth = byId.get(id);
    if (pth && !seen.has(pth)) addedHeadcount.push(id);
    add(pth);
  }
}

// СЛОВАРЬ СИНОНИМОВ — ТОЖЕ КОДОМ, И ПО ТОЙ ЖЕ ПРИЧИНЕ.
//
// Заказчик называет данные СВОИМИ словами: «покраска», «HQ», «BigOps»,
// «стрим», «юнит», «грейд». Мост от этих слов к именам полей есть только
// в rc-field-synonyms: в каталоге ни слова «покраска», ни «HQ» в описаниях
// полей нет, и поиск по смыслу их не находит никогда.
//
// Живой прогон 2026-08-31 показал цену пропуска дважды за один день.
// В выгрузке роутер словарь ЗАПРОСИЛ, но промахнулся путём — и бот написал
// в ТЗ «поля HQ/Line/Support не обнаружено», имея это поле в потерянной
// статье. В личке словаря не оказалось вовсе, и «HQ» ушло искаться среди
// названий управленческих подразделений, где его нет и быть не может;
// заказчику уехал запрос по трём подразделениям, подобранным «по смыслу».
//
// Резолв путей это чинит наполовину: он спасает промах, но не забывчивость.
// Поэтому словарь добирается кодом — на том же гейте, что sql-conventions
// и активная численность, и по тому же доводу: там, где пишется select
// или собирается состав выгрузки, слово заказчика ОБЯЗАНО быть переведено
// в имя поля, а словесное обязательство модель не держит.
//
// ГЕЙТ СНЯТ 01.09, И ЭТО ЗАКРЫТИЕ ТОЙ ЖЕ ПЕТЛИ. Правило написано ПОТОМУ ЧТО
// «в личке словаря не оказалось вовсе» — и посажено на `isQueryHelp || isExport`.
// В личке формы нет, тема пустая, isExport ложно: гейт не срабатывал ровно
// там, ради чего правило заводили. Полтора месяца словарь не доезжал до лички
// ни разу, а по виду прогона это неотличимо от «слово и так понятно».
//
// Теперь словарь едет вместе с витриной по умолчанию и по тому же доводу:
// витрина — основание, а словарь — единственный мост от слов заказчика
// к её полям. Читать витрину и не читать словарь значит дать автору
// инвентарь из 289 имён и не дать способа выбрать нужное.
const SYNONYM_IDS = ['rc-field-synonyms'];
const addedSynonyms = [];
if (!plan.no_question) {
  for (const id of SYNONYM_IDS) {
    const pth = byId.get(id);
    if (pth && !seen.has(pth)) addedSynonyms.push(id);
    add(pth);
  }
}

// Ссылка на юнит: рецепт перевода плюс справочник ТОЙ структуры, которую
// назвала сама ссылка. Второй справочник не добираем — его инвентарь только
// путал бы автора, а какая структура нужна, из ссылки известно точно.
const UNIT_LINK_IDS = ['rc-unit-link'];
const addedUnitLink = [];
if (isUnitLink) {
  const ids = UNIT_LINK_IDS.concat(
    unitLinkKind === 'management' ? ['t-management-unit'] : ['t-functional-unit']);
  for (const id of ids) {
    const pth = byId.get(id);
    if (pth && !seen.has(pth)) addedUnitLink.push(id);
    add(pth);
  }
}

const addedUnit = [];
if (isUnitQuestion) {
  for (const id of UNIT_IDS) {
    const p = byId.get(id);
    if (p && !seen.has(p)) addedUnit.push(id);
    add(p);
  }
}

// Отчёты для самостоятельной выгрузки: код ищет совпадение ключевых слов
// таблицы «Самостоятельные выгрузки» по ВСЕМУ тексту обращения — тот же
// принцип, что у мастеров домена и плейбука выгрузки: словесное обязательство
// («предложи самообслуживание, если подходит») модель не держит, поэтому
// кандидата находит код, а решение и формулировку оставляем автору.
// Совпадение ключевого слова — только сигнал «показать этот отчёт», а не
// гарантия покрытия: бот не видит инвентарь полей отчёта и не должен
// изображать, что сверил его с запросом.
// Гейт у подсказки про самообслуживание — свой, шире режима выгрузки: кроме
// темы принимается слово «выгруз» в тексте. В личке формы нет вовсе, человек
// пишет «нужна выгрузка логинов моей команды» — и не предложить ему готовый
// отчёт значит завести задачу на аналитика там, где он справился бы сам
// за минуту (в выгрузке канала таких случаев несколько, и все закрыты
// ответом «данные есть в Детальных списках»).
//
// Шире — но не бесплатно и не безобидно настолько, чтобы гейт снять вовсе:
// совпадение добавляет объект в DD Lookup (от одного до тринадцати запросов)
// и блок в материалы. Поэтому текст, где про выгрузку не сказано, отчёты
// не ищет: вопрос «где посмотреть табельный номер» — это вопрос по отчётам,
// у него свой маршрут, а не подсказка про самостоятельную выгрузку.
// Матчинг идёт по тексту, который написал ЧЕЛОВЕК, а не по служебному
// тексту формы. Haystack считается ОДИН раз и вне гейта самообслуживания:
// им пользуются и отчёты-трансформеры, и маршруты к экспертам, а гейты
// у них разные. Пока он жил внутри `if (selfServiceOn)`, второй потребитель
// получил бы либо пустую строку, либо копию правил чистки — а копия
// разъезжается молча, ровно как разъезжается список полей.
//
// Из haystack убирается:
//   шапка «Cross Data | … от пользователя @X»;
//   подписи полей — любая строка, кончающаяся двоеточием;
//   всё в круглых скобках.
//
// Скобки — главное здесь, и это НЕ то же самое, что «оставить значения
// полей». Прогон 2026-08-17: в обращении про логины юнита совпало
// единственное слово «фио», и не из подписи поля, а из ЗНАЧЕНИЯ —
// варианта выпадающего списка чувствительности «Персональные данные
// сотрудников (неполное ФИО, логин, раб. почта, возраст, master ID
// и др. внутренние ID)». Вариант этот одинаков во всех обращениях про ПДн,
// то есть отчёт предлагался бы по служебному тексту в каждом втором
// обращении. Ложное совпадение хуже промаха: предложение, которое
// появляется всегда, перестают читать.
//
// Правило про двоеточие здесь АГРЕССИВНЕЕ, чем LABEL_RE в guard'е адаптера
// (там ограничение в 60 символов). Причина в разной цене ошибки: guard
// обязан не потерять ЗНАЧЕНИЕ поля, а здесь надо не оставить ПОДПИСЬ, и
// подписи формы длинные — «Перечисли логины сотрудников, кому необходимо
// дать доступ к выгрузке:» это 69 символов и содержит слово «логин»,
// то есть под 60 символов не попадает и совпала бы в каждой выгрузке.
//
// Цена обоих правил: суть, написанная только внутри скобок или в строке
// с двоеточием на конце, не совпадёт. Это промах, а не ошибка — автор
// отвечает как обычно, просто без подсказки.
//
// И отдельно — ЗНАЧЕНИЕ ПОД ПОДПИСЬЮ «СРОК» выбрасывается вместе
// с подписью. «Срок:» в форме это когда файл нужен ЗАКАЗЧИКУ, а не за
// какой период считать данные: строка «14.07» под ней означает
// «к 14 июля». Читатель haystack'а, который проверяет, назвал ли человек
// период данных (детектор лишнего вопроса про дату), принял бы эту дату
// за названный период и промолчал бы ровно там, где бот переспрашивает зря.
//
// Правило про ПРЕДЫДУЩУЮ строку, а не про соседство в одной: подпись
// и значение в форме всегда стоят разными строками, и искать «срок» рядом
// с датой в одной строке значило бы не поймать ровно тот случай, ради
// которого правило заведено. Выбрасывается ровно одна строка — первая
// непустая после подписи, — а не всё до следующей подписи: значение поля
// формы однострочное, а хвост может оказаться уже свободным текстом.
const DEADLINE_LABEL = /(^|[^а-яё])срок|дедлайн|когда нужн|к какому числ/i;
const haystackLines = [];
{
  let prevLabel = '';
  const raw = question0
    .split('\n')
    .slice(/^cross data\s*\|/i.test(head0) ? 1 : 0)
    .map((l) => l.replace(/^[\s>*_#`~]+/, '').replace(/[\s*_`~]+$/, '').trim());
  for (const l of raw) {
    if (l.endsWith(':')) { prevLabel = l; continue; }
    if (l && DEADLINE_LABEL.test(prevLabel)) { prevLabel = ''; continue; }
    if (l) prevLabel = '';
    haystackLines.push(l);
  }
}
const haystack = haystackLines
  .join('\n')
  .replace(/\([^)]*\)/g, ' ')
  .toLowerCase();

const MAX_SELF_SERVICE = 2;
const selfServiceAll = [];
const selfServiceOn = isExport || /выгруз/i.test(question0);
if (selfServiceOn) {
  // Граница — следующая секция, а не конец файла. Без неё строки таблицы
  // «Маршруты» (свой формат колонок) разобрались бы как отчёты: id взялся бы
  // из колонки «маршрут», ключевые слова — из своей, byTitle дал бы фолбэк
  // на сам id, и бот предлагал бы «самостоятельную выгрузку» под названием
  // «payroll». Ошибка ровно того класса, из-за которого граница уже стоит
  // у таблицы «Сущности».
  for (const c of rows('## Самостоятельные выгрузки')) {
    const id = c[0];
    const keywords = String(c[1] || '')
      .split(',')
      .map((s) => s.trim().toLowerCase())
      .filter(Boolean);
    const matched = keywords.filter((kw) => kw && haystack.includes(kw));
    if (matched.length) {
      selfServiceAll.push({
        id, title: byTitle.get(id) || id, urn: byUrn.get(id) || '',
        // По какому слову отчёт попал в материалы. Поле диагностическое:
        // ровно его не хватало, чтобы увидеть совпадение по служебному
        // тексту, — «отчёт предложен» и «отчёт предложен по слову из
        // подписи поля» по выходу ядра не отличались никак.
        matched: matched.slice(0, 3),
      });
    }
  }
}
const selfServiceDropped = selfServiceAll.slice(MAX_SELF_SERVICE).map((s) => s.id);
const selfService = selfServiceAll.slice(0, MAX_SELF_SERVICE);
for (const s of selfService) {
  if (s.urn && !plan.dd.some((d) => d.urn === s.urn)) {
    plan.dd.push({ urn: s.urn, hint: '' });
  }
}

// ------------------------------------------- маршруты к эксперту по теме
//
// В фидбеке аналитика за 14–26 августа 13 обращений из 49 решались тем, что
// дежурный звал эксперта по теме: ответа в базе на них нет и быть не может,
// а бот отвечал по витринам, потому что домен формально определялся.
//
// ЭТО НЕ «ОБРАЩЕНИЕ НЕ К НАМ». Часть экспертов — сотрудники CrossData:
// есть доменные области, где дежурный экспертизой не обладает, и по флоу
// зовётся тот, кто обладает; обращение при этом остаётся нашим. Часть
// адресатов действительно в других командах, но разделять их отдельным
// признаком незачем — действие одно и то же, и любая формулировка вида
// «это ведёт не наша команда» была бы неверной для половины строк таблицы.
//
// ГЕЙТА НЕТ, в отличие от самообслуживания. Причина простая: у отчётов-
// трансформеров гейт защищает от расхода (совпадение добавляет объект в DD
// Lookup, до тринадцати HTTP-запросов), а маршрут не стоит ничего — только
// строка в материалах. Зато тема у него любая: «кто ведёт квоты» приходит
// и вопросом, и выгрузкой, и в личку без формы вовсе.
//
// ЗАЩИТА ОТ ЛОЖНОГО СОВПАДЕНИЯ — не гейт, а сам список слов, и он выверен
// по выгрузке канала: маршрут срабатывает на 3 % строк (7 из 204), каждое
// срабатывание по адресу. Слова вроде «найм», «кандидат», «оклад», «рид»
// из списка выброшены именно по этой проверке — они били по нашим же
// обращениям. Правило записано над таблицей в kb/index.md: новое слово
// проверяется по выгрузке, потому что совпадение идёт ПОДСТРОКОЙ и на глаз
// это не видно («рид» внутри «гибрид», «оклад» внутри «доклад»).
//
// Эксперт НЕ заменяет ответ и НЕ трогает уверенность. Обратный порядок
// превратил бы бота в справочную «идите к такому-то» и обесценил его там,
// где он полезен; а понижение уверенности за найденного эксперта было бы
// прямо неверным — это дополнительное знание, а не пробел.
const MAX_ROUTES = 2;
const routesAll = [];
for (const c of rows('## Маршруты')) {
  // Строка признаётся маршрутом ПО ФОРМЕ, а не по тому, что лежит в секции:
  // пять колонок и дата в последней. В той же секции живёт пояснительная
  // таблица «какие слова выброшены и почему» — у неё две колонки, и без этой
  // проверки её строки разобрались бы маршрутами: «найм» стал бы id, а вся
  // фраза после него — списком ключевых слов. Прозу над таблицей правят чаще,
  // чем код, и разъезжается это молча.
  //
  // Строка без даты не сработает вовсе — и это осознанно. Валидатор базы
  // знаний (check_routes) на неё ругается громко, до коммита; парсер же
  // обязан не пустить в черновик маршрут, про который неизвестно, когда его
  // последний раз подтверждали. Тихо промолчать здесь дешевле, чем тихо
  // назвать уволившегося человека.
  if (c.length < 5 || !/^\d{4}-\d{2}-\d{2}$/.test(String(c[4] || '').trim())) continue;
  const keywords = String(c[1] || '')
    .split(',')
    .map((x) => x.trim().toLowerCase())
    .filter(Boolean);
  const matched = keywords.filter((kw) => kw && haystack.includes(kw));
  if (!matched.length) continue;
  const dash = (v) => { const t = String(v || '').trim(); return t === '—' ? '' : t; };
  routesAll.push({
    id: c[0],
    who: dash(c[2]),
    where: dash(c[3]),
    // Дата подтверждения едет вместе с именем и печатается ДЖУНУ.
    // Маршрут — утверждение про человека, и оно протухает молча: владельца
    // отчёта мы для этого и не дублируем в git, а берём онлайн из DD.
    // Здесь взять неоткуда — объекта «кто ведёт квоты» в каталоге нет, —
    // поэтому единственная защита это видимая дата. Без неё просроченный
    // маршрут работает до первого «он уволился полгода назад».
    checked: dash(c[4]),
    // По какому слову маршрут попал в материалы — то же диагностическое
    // поле, что у самообслуживания. Без него «маршрут найден» и «маршрут
    // найден по слову из шаблона формы» по выходу ядра неотличимы.
    matched: matched.slice(0, 3),
  });
}
const routesDropped = routesAll.slice(MAX_ROUTES).map((r) => r.id);
const routes = routesAll.slice(0, MAX_ROUTES);

// ВСЕ адресаты таблицы, а не только совпавшие. Нужны, чтобы поймать имя,
// названное в черновике без совпадения: живой прогон 2026-08-27 показал
// черновик, где бот подключил в тред человека из таблицы на вопросе, где
// ни одно ключевое слово маршрута не срабатывает. Неверное имя в треде —
// ошибка, видимая заказчику, и молчать о ней нельзя.
const routeNames = [];
for (const c of rows('## Маршруты')) {
  if (c.length < 5 || !/^\d{4}-\d{2}-\d{2}$/.test(String(c[4] || '').trim())) continue;
  for (const v of [c[2], c[3]]) {
    const t = String(v || '').trim();
    if (t && t !== '—') for (const one of t.split(',')) {
      const n = one.trim();
      if (n && !routeNames.includes(n)) routeNames.push(n);
    }
  }
}

// ------------------------------------ витрина по умолчанию: какая и почему
//
// Живой прогон 2026-08-27: «где взять инфу о количестве биай аналитиков
// в стриме дата 15 грейда в юните human capital origination». Роутер вернул
// пустые domains и пустые articles — значит мастера не добирались, читать
// было нечего, и бот честно ответил «нет ответа». А ответ в базе есть:
// это обычная численность с фильтрами по грейду, стриму и юниту, и считается
// она по мастер-витрине сотрудников.
//
// Пустой план — это отказ РОУТЕРА, а не пробел базы, и отвечать на него
// «нет ответа» значит выдавать одно за другое. Слова заказчика в таблице
// «Домены» дополнены по выгрузке канала (грейд, юнит, стрим, специализация,
// должность), но дыры у роутера будут всегда: догонять их словами — гонка
// без конца, а страховка нужна одна.
//
// ВИТРИНА ПО УМОЛЧАНИЮ ВЫВОДИТСЯ ИЗ РЕЕСТРА, а не вписана в сборщик:
// это сущность, назначенная мастером в наибольшем числе доменов. Своя
// константа здесь была бы четвёртым местом, где живёт одно знание, —
// и разъехалась бы молча, как разъезжается список полей. Тест держит
// вывод: если реестр изменится так, что умолчание переедет, он покраснеет
// и решение примет человек.
//
// РОУТЕР НЕ ДАЛ НИЧЕГО — отдельный признак, и он НЕ равен «витрину добрал код».
// Раньше это было одно и то же: витрина добиралась только на пустом плане,
// и по факту её добора считался router_empty в телеметрии. Теперь витрина
// приезжает всегда, а сигнал «роутер промолчал» должен остаться прежним —
// иначе он покажет сто процентов промахов на ровном месте.
const routerEmpty = !plan.domains.length && !plan.articles.length && !plan.no_question;

// РОУТЕР НАЗВАЛ ТЕМУ, НО НИ ОДНОЙ СТАТЬИ — отдельный признак, и это НЕ то же
// самое, что «не дал ничего».
//
// Живой прогон 02.09: «где мне взять инвалидов, у которых есть дети». Один
// раз статья про витрину с детьми была названа и ответ вышел с первого захода,
// другой раз не была — и бот честно сказал, что данных о детях в материалах
// нет. Вопрос тот же, поведение разное: выбрать одну строку из 51 модель
// повторяемо не умеет, и требовать этого от неё бессмысленно.
//
// Чинится это не уговорами роутера, а мастерами домена: назвать тему из десяти
// — задача много проще, чем строку из 51, и остальное добирает код. Но чтобы
// увидеть, работает ли страховка, промах надо СЧИТАТЬ. Признак «домен есть,
// статей нет» — это ровно та доля обращений, где всё зависит от мастеров.
const routerDomainOnly =
  plan.domains.length > 0 && !plan.articles.length && !plan.no_question;

// ВИТРИНА СОТРУДНИКОВ ЧИТАЕТСЯ ВСЕГДА, а не только когда роутер промолчал.
//
// Живой прогон 01.09: «все сотрудники, у которых подтверждённая инвалидность».
// Роутер вернул пустоту — в таблице «Домены» нет слова «инвалидность», и это
// НОРМАЛЬНО: перечислить в алиасах все 289 полей витрины нельзя, а догонять
// их словами — гонка без конца, о которой здесь уже написано ниже.
//
// Вопрос при этом очевидно про сотрудников, и ответ лежал в витрине.
// Поэтому правило переворачивается: витрина — не страховка на случай
// промаха роутера, а ОСНОВАНИЕ по умолчанию. Роутер добавляет к ней
// частности, а не открывает к ней доступ.
//
// Цена — одна статья в материалах на каждом обращении при потолке в 16.
// Довод «дорого по токенам» в этом проекте снят отдельно и измеренно:
// запас по контексту тридцатикратный, и потолки здесь ограничивают число
// запросов и внимание автора, а не контекст.
//
// ВИТРИНА ПО УМОЛЧАНИЮ ВЫВОДИТСЯ ИЗ РЕЕСТРА, а не вписана в сборщик:
// это сущность, назначенная мастером в наибольшем числе доменов. Своя
// константа здесь была бы четвёртым местом, где живёт одно знание.
// Витрина по умолчанию выводится из реестра: сущность, назначенная мастером
// в наибольшем числе доменов. Своя константа была бы четвёртым местом,
// где живёт одно знание, и разъехалась бы молча.
let defaultMartId = '';
{
  const freq = new Map();
  for (const ids of masters.values()) {
    for (const id of ids) freq.set(id, (freq.get(id) || 0) + 1);
  }
  let bestN = 0;
  for (const [id, n] of freq) {
    if (n > bestN) { defaultMartId = id; bestN = n; }
  }
}

const addedMasters = [];
for (const d of plan.domains) {
  for (const id of masters.get(d) || []) {
    const p = byId.get(id);
    if (p && !seen.has(p)) addedMasters.push(id);
    add(p);
  }
}

// ВИТРИНА СОТРУДНИКОВ ЧИТАЕТСЯ ВСЕГДА — ПОСЛЕ мастеров домена, а не вместо них.
//
// Живой прогон 01.09: «все сотрудники, у которых подтверждённая инвалидность».
// Роутер вернул пустоту — слова «инвалидность» в таблице «Домены» нет, и это
// НОРМАЛЬНО: перечислить в алиасах все поля витрины нельзя, а догонять их
// словами — гонка без конца. Вопрос при этом очевидно про сотрудников,
// и ответ лежал в витрине.
//
// Поэтому правило переворачивается: витрина — не страховка на случай промаха
// роутера, а ОСНОВАНИЕ по умолчанию. Роутер добавляет к ней частности,
// а не открывает к ней доступ.
//
// ПОСЛЕ мастеров, и это не косметика: у юридического вопроса вести должен
// `t-legal-position`, а витрина сотрудников идти следом. Если домен назвал
// её своим мастером — она уже прочитана, и здесь не добавляется ничего:
// addedDefaultMart пуст, а added_masters сохраняет прежний смысл.
//
// Цена — одна статья при потолке в 16. Довод «дорого по токенам» в этом
// проекте снят отдельно и измеренно: запас по контексту тридцатикратный.
const addedDefaultMart = [];
if (!plan.no_question) {
  const p = byId.get(defaultMartId);
  if (p && !seen.has(p)) { addedDefaultMart.push(defaultMartId); add(p); }
}

// РЕЕСТР — ИСТОЧНИК ПРАВДЫ ДЛЯ ПУТЕЙ, А НЕ ПАМЯТЬ РОУТЕРА.
//
// Живой прогон 2026-08-31, выгрузка про образовательные программы. Роутер
// назвал `kb/field-synonyms.md`; настоящий путь — `kb/recipes/field-synonyms.md`.
// Разошлись они на одну папку, и потерялась при этом ровно та статья,
// в которой лежал ответ: словарь «слово заказчика → поле», а в нём строка
// `HQ / Line / Support → emp_specialization_oper_code`. Бот сам понял, чего
// ему не хватает, сам попросил — и написал в ТЗ «поле не обнаружено».
// В тот же день на вопросе «сколько сотрудников по покраске HQ и BigOps»
// он ушёл искать HQ в названиях управленческих юнитов: без словаря «HQ»
// выглядит как подразделение, а поиск по смыслу здесь не спасает никогда —
// в описании поля стоит «Отношение специализации к операционной
// деятельности», слов «HQ» и «покраска» там нет вовсе.
//
// Отказ тихий вдвойне: путь уезжал в articles_invented, тот шёл в «Задачу
// для базы» строкой «промах роутера, править нечего» — и уверенность
// НЕ ПОНИЖАЛ. То есть по логу потеря статьи и «такой статьи нет» выглядели
// одинаково, притом что статья есть и её читали десятки раз до этого.
//
// Лечится тем же приёмом, что мастера домена и инвентарь витрин: знание
// переезжает из памяти модели в код. Роутеру теперь велено называть `id`
// сущности, а путь подставляет реестр — тогда выдуманный путь невозможен
// ПО КОНСТРУКЦИИ, а не по дисциплине. Три ступени, в порядке надёжности:
const knownPaths = new Set(byId.values());
// basename → пути реестра. Для восстановления промаха в папке: имя файла
// модель помнит верно, ошибается в каталоге — так и было с field-synonyms.
const byBase = new Map();
for (const p of knownPaths) {
  const b = p.slice(p.lastIndexOf('/') + 1).toLowerCase();
  if (!byBase.has(b)) byBase.set(b, []);
  byBase.get(b).push(p);
}
const invented = [];
const resolvedById = [];      // роутер назвал id — путь взят из реестра
const recovered = [];         // [{said, path}] — промах в папке восстановлен
const routerPaths = [];       // что в итоге прочитано по выбору роутера
for (const raw of plan.articles) {
  const p = String(raw ?? '').trim();
  if (!p || p === '—') continue;
  // 1. Путь дословно из реестра — обычный случай.
  if (knownPaths.has(p)) { routerPaths.push(p); add(p); continue; }
  // 2. Назван id сущности. Основная форма после этой правки.
  const fromId = byId.get(p);
  if (fromId) { resolvedById.push(p); routerPaths.push(fromId); add(fromId); continue; }
  // 3. Промах в папке. Восстанавливаем ТОЛЬКО при единственном кандидате:
  //    два файла с одним именем в разных папках — это уже догадка, а тихо
  //    прочитать не ту статью хуже, чем не прочитать никакую.
  const cand = byBase.get(p.slice(p.lastIndexOf('/') + 1).toLowerCase()) || [];
  if (cand.length === 1) {
    recovered.push({ said: p, path: cand[0] });
    routerPaths.push(cand[0]);
    add(cand[0]);
    continue;
  }
  // 4. Восстановить нечем. Путь всё равно уходит в чтение: 404 от GitLab
  //    отделяет «роутер придумал» от «реестр ссылается на несуществующий
  //    файл» — два разных диагноза, и починка у них разная.
  invented.push(p);
  routerPaths.push(p);
  add(p);
}

// Предохранитель на объём. Резать молча нельзя, поэтому обрезанное
// называется в служебном блоке.
//
// ПОТОЛОК ОБЯЗАН БЫТЬ НЕ-СВЯЗЫВАЮЩИМ, и это главное про него. Порядок
// добора здесь такой: сначала статьи, добранные КОДОМ (плейбук выгрузки,
// развилка структуры, маршрутизация, sql-conventions, активная численность,
// словарь синонимов, поиск юнита, мастера домена), и только ПОТОМ — то,
// что подобрал роутер под сам вопрос. Значит обрезка по потолку срезает
// именно подобранное под вопрос, а не служебное. Потолок, который
// срабатывает, работает ровно наоборот замыслу.
//
// Считаем худший случай: кодом добирается до 10 статей (7 констант выше
// плюс до трёх мастеров), роутеру его собственный промпт разрешает 6.
// Шестнадцать — это сумма, то есть потолок перестаёт быть механизмом отбора
// и остаётся тем, чем задуман: предохранителем от вырожденного плана.
//
// Восемь ставились по прикидке «~18k токенов», и прикидка эта была вдвойне
// негодной: ориентир «резать после 40 000» тоже был придуманным числом,
// а настоящий потолок — 240 000 (на нём упал tool-loop: 242 618 токенов,
// quota tpm limit exceeded). При ≈ 32 000 на выгрузку запас семикратный,
// и шестнадцать статей его не расходуют. Расход при этом ИЗМЕРЯЕТСЯ —
// materials_len уезжает в телеметрию, — так что следующее решение
// принимается по распределению, а не по осторожности.
const MAX_ARTICLES = 16;
const dropped = ordered.slice(MAX_ARTICLES);
const files = ordered.slice(0, MAX_ARTICLES);

// ------------------------------------- инвентарь прочитанных витрин: кодом
//
// Живой прогон 2026-08-27, обращение из инфобеза про телефоны подрядчиков.
// В служебном блоке стояло «метаданные: 1728» — то есть из каталога пришёл
// ровно ОДИН объект, отчёт, а инвентарь витрины mdm_employee_structure_d
// не запрашивался вообще. При этом в ТЗ бот написал: «в метаданных витрины
// mdm_employee_structure_d нет поля с мобильным телефоном». Утверждение
// о факте, которого он не видел; поле в каталоге есть.
//
// Отчёт попал в план кодом (таблица самообслуживания), а витрину должен был
// назвать роутер — и не назвал. Тот же класс, что мастера домена и плейбук
// выгрузки: словесное обязательство модель не держит, значит решение
// переезжает в код. Статья про витрину прочитана — её состав полей
// запрашивается, и это свойство конструкции, а не дисциплины роутера.
//
// ПУСТОЙ hint НАМЕРЕННО. Инвентарь без фильтра — это полный список имён
// полей одним запросом (289 имён ≈ 3 КБ), а не тринадцать запросов
// за описаниями. Дёшево и, главное, ПОЛНО: именно полнота здесь и была
// нужна — вопрос стоял «есть ли такое поле вообще». Угадывать фильтр
// за роутера было бы ровно тем угадыванием, от которого защищает
// документированное поведение «промах фильтра возвращает инвентарь».
// Если роутер этот же URN уже назвал со своим hint — не трогаем: его фильтр
// даёт ещё и описания, а пустой их не даёт.
// ГЕЙТ: только выгрузка и просьба помочь с запросом. Там состав полей —
// это то, из чего собирается ответ: ТЗ перечисляет поля поимённо, select
// их пишет. На вопрос «что такое текучесть» отвечает статья, а полный
// список из 289 имён был бы 3 КБ шума и расхода на КАЖДОМ обращении.
// Гейт тот же, что у sql-conventions, и по той же причине.
// ИНВЕНТАРЬ ВИТРИНЫ ПО УМОЛЧАНИЮ БЕРЁТСЯ ВСЕГДА, гейт на неё не действует.
//
// Гейт `isExport || isQueryHelp` оставлен для ОСТАЛЬНЫХ витрин: там полный
// список имён — это шум на вопросе «что такое текучесть».
//
// Но у витрины сотрудников роль другая, и промах 01.09 показал какая.
// Вопрос «все сотрудники с подтверждённой инвалидностью» не выгрузка
// (в личке формы нет вовсе) и не просьба про запрос — гейт не сработал,
// инвентарь не запросили, и бот ответил, что признака в витринах нет.
// Признак есть: `disability_flg`, ярлык чувствительности EMP_SENS.
// (Имя сверено с карточкой колонки в каталоге: `disability_confirmed_flg`,
// как бот назвал его вторым заходом, не существует.)
//
// «Есть ли такое поле» — вопрос, на который отвечают ДАННЫЕ, а не проза
// статьи. Статья про витрину состав полей не перечисляет и не должна:
// он живёт в каталоге. Значит там, где витрина прочитана, её инвентарь
// обязан приехать вместе с ней — иначе автор судит о наличии поля
// по тексту, который про наличие полей ничего не говорит.
const needInventory = isExport || isQueryHelp;
const tablesRead = files
  .map((p) => tableByPath.get(p))
  .filter(Boolean)
  .filter((t) => needInventory || t.id === defaultMartId);
const addedDd = [];
for (const t of tablesRead) {
  if (plan.dd.some((d) => d.urn === t.urn)) continue;
  // ИНВЕНТАРЬ ВИТРИНЫ ПО УМОЛЧАНИЮ ВСТАЁТ В НАЧАЛО ОЧЕРЕДИ, а не в хвост.
  //
  // Потолок режет хвост, и приписанный в конец инвентарь витрины уезжал
  // первым же: стоило роутеру назвать четыре объекта — и он не запрашивался
  // вовсе. Это ровно тот отказ, ради которого правило и заводилось: витрина
  // читается всегда, а «всегда, если роутер не занял места» — это не всегда.
  // Роутер добавляет частности к основанию, поэтому основание идёт первым
  // и здесь тоже.
  if (t.id === defaultMartId) plan.dd.unshift({ urn: t.urn, hint: '' });
  else plan.dd.push({ urn: t.urn, hint: '' });
  addedDd.push(t.urn);
}
// Потолок применяется ЗАНОВО: добор мог его перебрать. Обрезанное
// приписывается к тому же ddDropped — режем не молча.
if (plan.dd.length > MAX_DD) {
  for (const d of plan.dd.slice(MAX_DD)) ddDropped.push(d.urn);
  plan.dd = plan.dd.slice(0, MAX_DD);
}

return [{
  json: {
    files,
    dropped,
    added_masters: addedMasters,
    // Режим выгрузки: определён по теме формы, то есть по сигналу человека.
    // Дальше по нему «Build materials» включает правила режима в промпт
    // автора, а «Parse answer» требует блок ТЗ. Одно решение — одно место.
    is_export: isExport,
    added_export: addedExport,
    // Обращение про доступ: своего режима у него нет, добирается только
    // статья процесса. Отдельным полем — чтобы в отчёте было видно, что
    // статью добрал код, а не выбрал роутер.
    is_access: isAccess,
    added_access: addedAccess,
    // Отчёты для самостоятельной выгрузки, найденные кодом по ключевым
    // словам. Пусто в режиме, отличном от выгрузки, — совпадение вне
    // is_export не проверяется вовсе, а не просто не показывается.
    self_service: selfService,
    self_service_dropped: selfServiceDropped,
    // Витрины, чьи СТАТЬИ уехали автору. «Build materials» сверяет этот
    // список с тем, по каким объектам инвентарь реально пришёл, и называет
    // разницу: статья прочитана, состав полей не получен — про такую витрину
    // утверждать отсутствие поля нельзя.
    tables_read: tablesRead,
    // Пути статей, описывающих МЕХАНИКУ витрины: сама витрина (ключи,
    // гранулярность, джойны) и фильтр активности. Они едут на каждом вопросе,
    // и названные в них поля — леса, а не ответ по существу: `mdm_employee_rk`
    // и `active_employee_flg` стоят почти в каждом черновике.
    // «Parse answer» вычитает их, когда считает, что закрыл каталог.
    // Пути отдаются отсюда, а не вписываются там: они живут в реестре,
    // и вторая копия разъехалась бы молча.
    mechanics_paths: [defaultMartId, ...HEADCOUNT_IDS]
      .map((id) => byId.get(id)).filter(Boolean),
    // Инвентарь, добранный кодом сверх плана роутера. Диагностическое поле:
    // без него «роутер назвал витрину» и «витрину добрал код» по выходу ядра
    // неотличимы, а это разные истории про качество роутера.
    dd_added_by_code: addedDd,
    // Просят помочь написать запрос. Отдельным полем, потому что читают его
    // двое: «Build materials» гасит по нему режим выгрузки, восстановленный
    // догадкой, а телеметрия считает, как часто такие обращения приходят.
    is_query_help: isQueryHelp,
    added_query: addedQuery,
    added_headcount: addedHeadcount,
    // Словарь «слово заказчика → поле». Добирается кодом там, где пишется
    // запрос или собирается состав выгрузки: без него «покраска» и «HQ»
    // не переводятся в имена полей ничем.
    added_synonyms: addedSynonyms,
    // Ссылка на юнит: что добрано и что из неё разобрано. Поля уезжают
    // в материалы автору — иначе он видит ссылку и не знает, что с ней
    // делать, — и в телеметрию: доля обращений со ссылкой на юнит это
    // отдельный класс, и мерить его надо с первого дня.
    added_unit_link: addedUnitLink,
    unit_link_kind: unitLinkKind,
    unit_link_id: unitLinkId,
    unit_link: isUnitLink,
    added_unit: addedUnit,
    is_unit_question: isUnitQuestion,
    // Текст, который написал ЧЕЛОВЕК: без шапки формы, без подписей полей,
    // без содержимого скобок и без значения под подписью «Срок».
    //
    // Считается здесь ОДИН раз и уезжает дальше готовым, потому что
    // читателей у него теперь двое: матчинг отчётов и маршрутов тут же,
    // и детектор лишнего вопроса про дату в «Parse answer». Вторая копия
    // правил чистки разъехалась бы молча — ровно так разъезжались список
    // тем формы, credential и модель. По сырому вопросу тот детектор
    // работать не может: подпись поля «Срок:» и вариант выпадающего списка
    // в скобках содержат слова про время, которых заказчик не писал.
    question_own: haystack,
    // Роутер не назвал ни домена, ни статьи — читалась витрина по умолчанию.
    // Отдельным полем: «роутер промахнулся» и «в базе нет ответа» это разные
    // вещи, и по выходу ядра они обязаны различаться. Оно же уезжает
    // в телеметрию — доля пустых планов это метрика качества роутера.
    added_default_mart: addedDefaultMart,
    router_empty_plan: routerEmpty,
    // Эксперты по теме, найденные кодом. Пустой список — это «слов
    // маршрута в обращении нет», а не «маршрута не существует»: таблица
    // покрывает то, что встретилось в фидбеке, и растёт по мере трафика.
    routes,
    routes_dropped: routesDropped,
    route_names: routeNames,
    // Что роутер выбрал САМ, отдельно от итога.
    //
    // Пустой router_articles при непустом files значит «точного совпадения
    // в реестре не нашлось, читались только мастера домена по умолчанию».
    // Живой прогон 2026-08-11 показал, зачем это отличать: роутер не вернул
    // ни одной статьи, но назвал домен, код добрал трёх мастеров — и автор
    // уверенно ответил по материалам не про то, о чём спрашивали. Инвариант
    // «мастера читаются всегда» сработал, а оснований под ответом не было.
    // Прочерк и пустые строки отбрасываются: путь «—» в реестре означает
    // «статьи нет», и считать его выбором роутера — значит принять пробел
    // базы за совпадение.
    // Что прочитано ПО ВЫБОРУ РОУТЕРА — уже после резолва: назван id или
    // промахнулся папкой, а статья всё равно та самая. Раньше здесь стоял
    // сырой список, и `masters_only` считался по нему же — то есть выбор
    // роутера засчитывался даже тогда, когда по нему ничего не прочиталось.
    router_articles: routerPaths,
    router_domain_only: routerDomainOnly,
    // Диагностика резолва. Оба поля печатаются джуну и уезжают в телеметрию:
    // доля восстановленных путей — это метрика того, насколько роутер держит
    // формат, и мерить её надо с первого дня. Задним числом «роутер назвал
    // путь неверно» и «статьи не было» по логу неразличимы.
    articles_by_id: resolvedById,
    articles_recovered: recovered,
    domains: plan.domains,
    dd: plan.dd,
    dd_dropped: ddDropped,
    // Число объектов вынесено отдельным полем: IF «Need DD» сравнивает его
    // с нулём. Условие по длине массива в n8n-выражении работает не везде
    // одинаково, а промах здесь тихий — метаданные просто не запросятся.
    // Пути, которых нет в реестре: роутер их придумал. Отдельно от
    // articles_failed — там пути ИЗ реестра, которые не удалось прочитать.
    articles_invented: invented,
    // ВОССТАНОВЛЕННАЯ тема и ссылка на отчёт. «Build materials» брал их
    // из сырых полей формы, а формы нет ни в чате, ни в личке — значит
    // правило «спрашивали про отчёт, а отчёта в материалах нет» там
    // не срабатывало НИ РАЗУ, и уверенность не понижалась. Ровно та же
    // асимметрия, из-за которой в чате не работало самообслуживание:
    // у режима выгрузки фолбэк был, у поиска отчёта — нет.
    topic_kind_used: topicKind,
    report_url_found: reportUrlFound,
    dd_count: plan.dd.length,
    no_question: plan.no_question,
    router_error: routerError,
    registry_error: registryError,
    router_raw: rawOut,
  },
}];

// Возвращает поля плана дальше по конвейеру, схлопывая поштучное чтение статей
// в один элемент. Сами тексты статей не тащим: их соберёт «Build materials»
// через $('Read article').all() — там же, где раскодировка base64.
const plan = $('Plan').first().json;
return [{ json: plan }];

// СОСТАВ ПОЛЕЙ ВИТРИНЫ — ЭТО СПИСОК, А НЕ ТЕКСТ БЛОКА.
//
// Разбор общий для «Build lookups» и «Build check SQL»: обе ноды отвечают
// на один вопрос — какие поля у витрины есть на самом деле, — и вторая копия
// разъехалась бы молча.
//
// Шейпер DD печатает состав в двух разборных формах: строка-перечень
// «a, b, c» (с ярлыком «ПОЛЯ:» или без) и маркер подробностей
// «— имя_поля (тип) [PK]». Всё остальное — описания и комментарии
// владельца — проза, и в инвентарь она не идёт: живой прогон 2026-08-31
// приписал витрине сотрудников `valid_to_dttm`, упомянутый в ОПИСАНИИ
// соседнего поля, и запрос упал на несуществующей колонке.
// ИМЯ ПОЛЯ БЫВАЕТ КОРОТКИМ, И ЭТО НЕ КРАЕВОЙ СЛУЧАЙ.
//
// Здесь стояло `{2,}`, то есть «не короче трёх символов», — и `id` под это
// не подходил. А проверка требует, чтобы идентификатором был КАЖДЫЙ элемент
// перечня: одно двухбуквенное имя делало неразборной всю строку целиком.
//
// Померено сквозным прогоном 2026-08-31 на витрине детей: `DD Lookup`
// отдаёт «ВСЕ ПОЛЯ ТАБЛИЦЫ: id, individualid, birthdate, …», ровно
// 25 имён, — а разбиралось из них НОЛЬ, и ядро объявляло, что каталог
// состава не дал. Бьёт по любой витрине с полем `id`, `dt`, `rk`.
// Регистр и ведущее подчёркивание допускаются: у витрин из внешних систем
// встречаются `CommonAddressId`, `Email`, `__contract__`. Строгий вариант
// `[a-z][a-z0-9_]+` требовал соответствия от КАЖДОГО элемента перечня, и одно
// такое имя роняло разбор всей строки в ноль — измерено на витрине детей.
const IDENT = /^[A-Za-z_][A-Za-z0-9_]*$/;

// СКОЛЬКО ПОЛЕЙ ШЕЙПЕР ОБЕЩАЛ. Нужно не для красоты: разбор идёт по формату,
// который пишет другая нода, и промах формата обязан быть громким. Обещано
// 25, разобрано 0 — это поломка РАЗБОРА, а не молчание каталога, и лечится
// она в другом месте. Без сверки эти два случая неразличимы, и один уже
// прожил сутки под видом другого.
function declaredOf(body) {
  const t = String(body || '');
  // Шейпер называет число полей в КАЖДОМ своём режиме, но по-разному:
  //   без фильтра     — «ПОЛНЫЙ ИНВЕНТАРЬ ПОЛЕЙ: 25»;
  //   фильтр по имени — «ПОЛЯ ПО ИМЕНИ «x»: 3 из 25»;
  //   поиск по смыслу — «проверены 25 из 25 полей»;
  //   обрезка лимитом — «ПОЛЯ: получено 300 из 500».
  // Берём ЧИСЛО ПОЛЕЙ ТАБЛИЦЫ, то есть второе в паре «N из M»: сверять
  // разбор надо с тем, сколько их всего, а не сколько совпало с фильтром.
  const pair = t.match(/(\d+)\s+из\s+(\d+)/);
  const m = t.match(/ПОЛНЫЙ ИНВЕНТАРЬ ПОЛЕЙ:\s*(\d+)/) ||
            t.match(/ПОДРОБНО ПО ПОЛЯМ\s*\((\d+)\)/);
  if (m) return Number(m[1]);
  if (pair) return Number(pair[2]);
  return /ПОЛЯ ИЗ DD:\s*0/.test(t) ? 0 : null;
}

function fieldsOf(body) {
  const set = new Set();
  for (const raw of String(body || '').split('\n')) {
    const line = raw.trim();
    if (!line) continue;
    const bullet = line.match(/^[—–-]\s*([A-Za-z_][A-Za-z0-9_]*)\b/);
    if (bullet) { set.add(bullet[1]); continue; }
    const list = line.replace(/^[^:]{0,60}:\s*/, '');
    if (!list.includes(',')) continue;
    const parts = list.split(',').map((x) => x.trim());
    if (parts.length >= 2 && parts.every((x) => IDENT.test(x))) {
      for (const x of parts) set.add(x);
    }
  }
  // ПЕРЕЧЕНЬ ПО СТРОКАМ: «имя — описание», по одному полю на строку.
  //
  // С 01.09 шейпер печатает инвентарь именно так: описания приходят тем же
  // ответом каталога, и выбрасывать их значит оставлять поля без подписи —
  // ровно то, из-за чего `disability_flg` уехал в запрос без комментария.
  // Разбор про этот формат не знал и видел ОДНО поле вместо всех: тот же
  // разъезд печатающей и читающей ноды, что 2026-08-31 прожил сутки под
  // видом молчания каталога. Здесь он стоил бы дороже — «поля нет в витрине»
  // там, где оно есть.
  //
  // Перечень ищется ПОДРЯД ИДУЩИМИ строками, а не по заголовку над ними.
  // Заголовок якорем не работает: между «ПОЛЯ ПО ИМЕНИ «x»: 0 из 10» и самим
  // списком шейпер ставит абзац прозы, и разбор от заголовка обрывался на
  // первой же русской строке. А привязка к тексту заголовка — это ещё один
  // контракт между двумя нодами, то есть ещё одно место для того же разъезда.
  //
  // Две подряд строки-идентификатора прозой не бывают, поэтому пара —
  // достаточный признак перечня, и лишнего он не наберёт: одиночное имя
  // разбирается ниже и только следом за заголовком про поля.
  {
    const ROW = /^([A-Za-z_][A-Za-z0-9_]*)(\s+[—–-]\s+\S.*)?$/;
    let run = [];
    const flush = () => {
      if (run.length >= 2) for (const x of run) set.add(x);
      run = [];
    };
    for (const raw of String(body || '').split('\n')) {
      const row = raw.trim().match(ROW);
      if (row) run.push(row[1]);
      else flush();
    }
    flush();
  }

  // Витрина с ОДНИМ полем перечнем не выглядит: запятой в строке нет,
  // и разбор давал пустой набор — то есть гейт выгрузки получал ложное
  // «метаданных не пришло». Одиночное имя принимается ТОЛЬКО следом
  // за заголовком про поля, иначе в инвентарь полезет любое слово прозы.
  if (!set.size) {
    const lines = String(body || '').split('\n').map((x) => x.trim());
    for (let i = 0; i < lines.length - 1; i++) {
      if (!/ПОЛ[ЕЙЯ]/i.test(lines[i])) continue;
      for (let j = i + 1; j < Math.min(i + 3, lines.length); j++) {
        if (lines[j] && IDENT.test(lines[j])) { set.add(lines[j]); break; }
      }
    }
  }
  return set;
}

// ЕДИНСТВЕННЫЙ РАЗБОР ОТВЕТА КАТАЛОГА — ЗДЕСЬ, И ЧИТАЮТ ЕГО ВСЕ.
//
// «Build lookups» и «Build materials» отвечали на один и тот же вопрос —
// дал ли каталог состав полей — КАЖДЫЙ СВОИМ разбором текста. Расхождение
// достижимо не «при следующем дрейфе», а прямо сейчас: `fieldsOf` требует
// соответствия IDENT от КАЖДОГО элемента перечня, и одно имя вида
// `CommonAddressId` или `__contract__` роняло разбор в ноль. Тогда одна
// нода уходила за составом в `information_schema`, а вторая уверенно
// печатала автору «Каталог состава этой витрины не дал» — два
// противоречащих утверждения в одних материалах.
//
// Теперь порядок один: СТРУКТУРА, потом текст запасным путём.
function ddFieldsOf(res) {
  const st = res && res.dd;
  // Основной путь: шейпер отдал структуру. Разбирать нечего.
  if (st && Array.isArray(st.fields) && st.fields.length) {
    return {
      names: st.fields.map((f) => String(f.name || '')).filter(Boolean),
      declared: Number.isFinite(st.total) ? st.total : st.fields.length,
      sensitive: st.fields.filter((f) => f.sensitive)
        .map((f) => String(f.name || '')).filter(Boolean),
      from: 'struct',
    };
  }
  // Совместимость: `DD Lookup` мог быть не переимпортирован.
  const flat = Array.isArray(res && res.dd_fields)
    ? res.dd_fields.map((f) => String(f || '').trim()).filter(Boolean)
    : [];
  if (flat.length) {
    return {
      names: flat,
      declared: Number.isFinite(res.dd_total) ? res.dd_total : flat.length,
      sensitive: [],
      from: 'legacy_fields',
    };
  }
  // Последний рубеж: старый субворкфлоу, только текст.
  const meta = String((res && res.dd_meta) || '');
  const set = fieldsOf(meta);
  return {
    names: [...set],
    declared: declaredOf(meta),
    sensitive: [],
    from: set.size ? 'legacy_text' : 'none',
  };
}

// ЗАПРОСЫ, КОТОРЫЕ НАДО СДЕЛАТЬ ДО АВТОРА. Их два вида, и оба про одно:
// у кода есть доступ к данным, а у автора нет, и всё, что можно узнать
// точно, он обязан получить фактом, а не заданием.
//
//   unit    — ссылка на юнит: `id` → `rk` → уровень, по рецепту;
//   columns — состав полей витрины, про которую каталог промолчал.
//
// Собираются одним списком, потому что уезжают в одну и ту же ноду Trino:
// она выполняется по разу на элемент, а разбор ответов разводится по `kind`.
const plan = $('Plan').first().json ?? {};
const kind = String(plan.unit_link_kind || '');
const id = String(plan.unit_link_id || '');
const jobs = [];

const q = (s) => "'" + String(s).replace(/'/g, "''") + "'";
// Фильтр версии и признаки удаления — через CAST в varchar: тип у флагов
// разный от витрины к витрине (`deleted_flg = 0` в одной, `= false`
// в другой), а отказ запроса здесь стоит дороже лишнего приведения —
// он превращает разрешённую ссылку в «проверить не удалось».
const alive = [
  // Жёсткое равенство, а не префикс: признак актуальной версии — конкретный
  // день, и статьи витрин пишут его конкретным. Приводится КОЛОНКА, а не
  // литерал: Trino строг по типам и varchar с timestamp не сравнивает,
  // а `CAST(... AS date)` работает и на date, и на timestamp.
  "CAST(valid_to_dttm AS date) = DATE '5999-01-01'",
  "CAST(deleted_flg AS varchar) IN ('0', 'false')",
];

let sql = '';
if (kind && id && kind === 'management') {
  // ДВА ШАГА РЕЦЕПТА В ОДНОМ ЗАПРОСЕ. Шаг 1 — `id` → `rk` по справочнику,
  // шаг 2 — «на каком уровне лежит этот `rk`» по витрине сотрудников.
  // Второй шаг зависит от результата первого, но это не повод ходить
  // дважды: подзапрос делает ту же зависимость внутри одного обращения.
  //
  // LEFT JOIN, а не INNER: юнит может существовать в справочнике и не иметь
  // ни одного активного сотрудника. При INNER такой юнит вернул бы ноль
  // строк — то есть выглядел бы как «идентификатор не найден», и автор
  // сказал бы заказчику неправду про его же ссылку.
  sql =
    'WITH u AS (\n' +
    '  SELECT CAST(management_unit_rk AS varchar) AS rk,\n' +
    '         CAST(management_unit_nm AS varchar) AS nm\n' +
    '  FROM prod_v_dds.management_unit\n' +
    '  WHERE CAST(management_unit_id AS varchar) = ' + q(id) + '\n' +
    '    AND ' + alive.join('\n    AND ') + '\n' +
    ')\n' +
    'SELECT u.rk AS unit_rk,\n' +
    '       u.nm AS unit_nm,\n' +
    '       CAST(e.management_unit_lvl_num AS varchar) AS lvl_num,\n' +
    '       CAST(e.mapped_management_unit_nm AS varchar) AS mapped_nm,\n' +
    '       count(e.mdm_employee_rk) AS emp_cnt\n' +
    'FROM u\n' +
    'LEFT JOIN prod_v_emart.mdm_employee_structure_d e\n' +
    '  ON CAST(e.mapped_management_unit_rk AS varchar) = u.rk\n' +
    ' AND e.last_day_flg = 1\n' +
    ' AND e.active_employee_flg = 1\n' +
    ' AND e.company_fire_flg = 0\n' +
    'GROUP BY u.rk, u.nm, e.management_unit_lvl_num, e.mapped_management_unit_nm\n' +
    'ORDER BY emp_cnt DESC\n' +
    'LIMIT 10';
} else {
  // Каталог продуктов: шага «найти уровень» здесь нет — с `functional_unit_rk`
  // идут в `t-functional-role`, где уровень не при чём. Зато берём
  // `management_unit_rk`: это единственный явный мост между структурами,
  // и достраивать его по названиям рецепт прямо запрещает.
  sql =
    'SELECT CAST(functional_unit_rk AS varchar) AS unit_rk,\n' +
    '       CAST(functional_unit_nm AS varchar) AS unit_nm,\n' +
    '       CAST(management_unit_rk AS varchar) AS mgmt_rk\n' +
    'FROM prod_v_dds.functional_unit\n' +
    'WHERE CAST(functional_unit_id AS varchar) = ' + q(id) + '\n' +
    "  AND CAST(close_flg AS varchar) IN ('0', 'false')\n" +
    '  AND ' + alive.join('\n  AND ') + '\n' +
    'LIMIT 5';
}

if (kind && id) {
  jobs.push({
    lookup_kind: 'unit',
    lookup_sql: sql,
    unit_kind: kind,
    unit_id: id,
    unit_table: kind === 'management' ? 'prod_v_dds.management_unit'
                                      : 'prod_v_dds.functional_unit',
  });
}

// СОСТАВ ПОЛЕЙ ИЗ ДАННЫХ, КОГДА КАТАЛОГ ПРОМОЛЧАЛ.
//
// Правило «имена полей берём в каталоге, а не дублируем в git» остаётся
// в силе: список в статье устаревает молча. Но у каталога есть ТРЕТИЙ исход
// помимо «ответил» и «не ответил» — он ответил, а состава полей не дал.
// Так бывает, когда URN в реестре собран по схеме и не подтверждён, или
// когда витрины в каталоге нет вовсе: она приехала из внешней системы.
//
// Живой прогон 2026-08-31: витрина детей `individualchildren_public` стояла
// в служебной строке «метаданные: …», то есть выглядела полученной, а автор
// писал «состав полей не получен, имена взяты из статьи и не подтверждены»
// и ставил среднюю уверенность. И так на КАЖДОМ вопросе про детей — сигнал,
// который горит всегда, перестают читать.
//
// Имена при этом лежат в самих данных и стоят один дешёвый запрос.
// Источник по смыслу тот же, что каталог: не статья, а витрина.
const planned = Array.isArray(plan.dd) ? plan.dd : [];
let ddResults = [];
try { ddResults = $('Call DD Lookup').all().map((i) => i.json); } catch (e) { ddResults = []; }
const seen = new Set();
planned.forEach((obj, idx) => {
  const m = String(obj?.urn || '').match(/table:([a-z0-9_]+)\.([a-z0-9_]+)/i);
  if (!m) return;                                  // отчёты таблицами не являются
  const schema = m[1].toLowerCase();
  const name = m[2].toLowerCase();
  const full = schema + '.' + name;
  if (seen.has(full)) return;
  // Каталог дал состав — спрашивать данные незачем. Разбор ОБЩИЙ
  // с «Build materials»: раньше каждая нода отвечала на этот вопрос своим
  // способом, и на одном и том же ответе они расходились.
  if (ddFieldsOf(ddResults[idx] || {}).names.length) return;
  seen.add(full);
  jobs.push({
    lookup_kind: 'columns',
    lookup_table: full,
    lookup_urn: String(obj.urn || ''),
    lookup_sql:
      'SELECT ' + q(full) + ' AS tbl, column_name, data_type\n' +
      'FROM information_schema.columns\n' +
      'WHERE table_schema = ' + q('prod_v_' + schema) + '\n' +
      '  AND table_name = ' + q(name) + '\n' +
      'ORDER BY ordinal_position\n' +
      'LIMIT 1000',
  });
});

if (!jobs.length) return [{ json: { lookup_needed: false } }];
return jobs.map((j) => ({ json: { lookup_needed: true, ...j } }));

// Нода Trino выполнилась по разу на элемент, и элементы у нас двух видов.
// n8n сохраняет соответствие «вход i → выход i», поэтому вид запроса
// берётся из плана по индексу — тем же приёмом, что порядок колонок
// в DD Lookup.
let jobs = [];
try { jobs = $('Build lookups').all().map((i) => i.json); } catch (e) { jobs = []; }

// «Узел не выполнялся» отличается от «выполнился и вернул ноль строк»
// ТОЛЬКО броском $(): при alwaysOutputData ноль строк приезжает пустым
// элементом, а список элементов может оказаться и пустым. Считать пустой
// список за «не выполнялся» значит превратить определённое «такого юнита
// в справочнике нет» в размытое «проверить не удалось» — то есть ровно
// в тот диагноз, ради разведения которого ветка и написана.
let items = null;
try { items = $('Run lookups').all().map((i) => i.json); } catch (e) { items = null; }

// СОСТАВ ПОЛЕЙ, ДОБРАННЫЙ ИЗ ДАННЫХ. Ключ — «схема.таблица» как в реестре.
// Пустой ответ — тоже ответ: витрины с таким именем в Trino нет, и это
// говорит про URN в реестре, а не про доступ.
const columns = {};
const colFailed = {};
jobs.forEach((j, idx) => {
  if (j.lookup_kind !== 'columns') return;
  const it = items ? items[idx] : null;
  if (!it || typeof it !== 'object') {
    colFailed[j.lookup_table] = 'узел не выполнялся'; return;
  }
  if (it.error || it.message) {
    colFailed[j.lookup_table] = String(it.error || it.message); return;
  }
  const list = Array.isArray(it.data) ? it.data : [it];
  const names = list.map((r) => String(r?.column_name || '')).filter(Boolean);
  if (names.length) columns[j.lookup_table] = names;
  else colFailed[j.lookup_table] = 'в Trino витрины с таким именем нет';
});

const wanted = jobs.find((j) => j.lookup_kind === 'unit') || null;
if (!wanted) {
  return [{ json: { unit_state: 'skip', columns, columns_failed: colFailed } }];
}
const unitItems = items === null ? null : [items[jobs.indexOf(wanted)]];

let rows = [];
const plan = wanted;
let failed = '';
for (const it of (unitItems || [])) {
  if (!it || typeof it !== 'object') continue;
  if (Object.keys(it).length === 0) continue;        // пустой ответ = строк нет
  if (it.error || it.message) { failed = String(it.error || it.message); continue; }
  const list = Array.isArray(it.data) ? it.data : [it];
  for (const r of list) if (r && r.unit_rk !== undefined && r.unit_rk !== null) rows.push(r);
}

if (items === null) {
  return [{ json: { unit_state: 'never_ran', columns, columns_failed: colFailed,
                    unit_kind: plan.unit_kind,
                    unit_id: plan.unit_id, unit_table: plan.unit_table } }];
}
if (failed) {
  return [{ json: { unit_state: 'failed', unit_error: failed,
                    columns, columns_failed: colFailed,
                    unit_kind: plan.unit_kind, unit_id: plan.unit_id,
                    unit_table: plan.unit_table } }];
}
if (!rows.length) {
  return [{ json: { unit_state: 'not_found', columns, columns_failed: colFailed,
                    unit_kind: plan.unit_kind,
                    unit_id: plan.unit_id, unit_table: plan.unit_table } }];
}

// Ключ один — строки различаются уровнем и названием среза. Берём ключ
// из первой строки: подзапрос справочника отфильтрован по версии, и разные
// `rk` здесь означали бы, что фильтр версии не сработал; тогда об этом
// надо сказать, а не выбирать молча.
const keys = [...new Set(rows.map((r) => String(r.unit_rk)))];
const levels = [...new Set(rows.map((r) => String(r.lvl_num || ''))
                              .filter((v) => v && v !== 'null'))];
const total = rows.reduce((a, r) => a + (Number(r.emp_cnt) || 0), 0);

return [{ json: {
  unit_state: 'found',
  columns,
  columns_failed: colFailed,
  unit_kind: plan.unit_kind,
  unit_id: plan.unit_id,
  unit_table: plan.unit_table,
  unit_rk: keys[0],
  unit_rk_many: keys.length > 1 ? keys : [],
  unit_nm: String(rows[0].unit_nm || ''),
  unit_mgmt_rk: String(rows[0].mgmt_rk || ''),
  unit_levels: levels,
  unit_emp_cnt: total,
  unit_rows: rows.slice(0, 10),
} }];

// СОСТАВ ПОЛЕЙ ВИТРИНЫ — ЭТО СПИСОК, А НЕ ТЕКСТ БЛОКА.
//
// Разбор общий для «Build lookups» и «Build check SQL»: обе ноды отвечают
// на один вопрос — какие поля у витрины есть на самом деле, — и вторая копия
// разъехалась бы молча.
//
// Шейпер DD печатает состав в двух разборных формах: строка-перечень
// «a, b, c» (с ярлыком «ПОЛЯ:» или без) и маркер подробностей
// «— имя_поля (тип) [PK]». Всё остальное — описания и комментарии
// владельца — проза, и в инвентарь она не идёт: живой прогон 2026-08-31
// приписал витрине сотрудников `valid_to_dttm`, упомянутый в ОПИСАНИИ
// соседнего поля, и запрос упал на несуществующей колонке.
// ИМЯ ПОЛЯ БЫВАЕТ КОРОТКИМ, И ЭТО НЕ КРАЕВОЙ СЛУЧАЙ.
//
// Здесь стояло `{2,}`, то есть «не короче трёх символов», — и `id` под это
// не подходил. А проверка требует, чтобы идентификатором был КАЖДЫЙ элемент
// перечня: одно двухбуквенное имя делало неразборной всю строку целиком.
//
// Померено сквозным прогоном 2026-08-31 на витрине детей: `DD Lookup`
// отдаёт «ВСЕ ПОЛЯ ТАБЛИЦЫ: id, individualid, birthdate, …», ровно
// 25 имён, — а разбиралось из них НОЛЬ, и ядро объявляло, что каталог
// состава не дал. Бьёт по любой витрине с полем `id`, `dt`, `rk`.
// Регистр и ведущее подчёркивание допускаются: у витрин из внешних систем
// встречаются `CommonAddressId`, `Email`, `__contract__`. Строгий вариант
// `[a-z][a-z0-9_]+` требовал соответствия от КАЖДОГО элемента перечня, и одно
// такое имя роняло разбор всей строки в ноль — измерено на витрине детей.
const IDENT = /^[A-Za-z_][A-Za-z0-9_]*$/;

// СКОЛЬКО ПОЛЕЙ ШЕЙПЕР ОБЕЩАЛ. Нужно не для красоты: разбор идёт по формату,
// который пишет другая нода, и промах формата обязан быть громким. Обещано
// 25, разобрано 0 — это поломка РАЗБОРА, а не молчание каталога, и лечится
// она в другом месте. Без сверки эти два случая неразличимы, и один уже
// прожил сутки под видом другого.
function declaredOf(body) {
  const t = String(body || '');
  // Шейпер называет число полей в КАЖДОМ своём режиме, но по-разному:
  //   без фильтра     — «ПОЛНЫЙ ИНВЕНТАРЬ ПОЛЕЙ: 25»;
  //   фильтр по имени — «ПОЛЯ ПО ИМЕНИ «x»: 3 из 25»;
  //   поиск по смыслу — «проверены 25 из 25 полей»;
  //   обрезка лимитом — «ПОЛЯ: получено 300 из 500».
  // Берём ЧИСЛО ПОЛЕЙ ТАБЛИЦЫ, то есть второе в паре «N из M»: сверять
  // разбор надо с тем, сколько их всего, а не сколько совпало с фильтром.
  const pair = t.match(/(\d+)\s+из\s+(\d+)/);
  const m = t.match(/ПОЛНЫЙ ИНВЕНТАРЬ ПОЛЕЙ:\s*(\d+)/) ||
            t.match(/ПОДРОБНО ПО ПОЛЯМ\s*\((\d+)\)/);
  if (m) return Number(m[1]);
  if (pair) return Number(pair[2]);
  return /ПОЛЯ ИЗ DD:\s*0/.test(t) ? 0 : null;
}

function fieldsOf(body) {
  const set = new Set();
  for (const raw of String(body || '').split('
')) {
    const line = raw.trim();
    if (!line) continue;
    const bullet = line.match(/^[—–-]\s*([A-Za-z_][A-Za-z0-9_]*) /);
    if (bullet) { set.add(bullet[1]); continue; }
    const list = line.replace(/^[^:]{0,60}:\s*/, '');
    if (!list.includes(',')) continue;
    const parts = list.split(',').map((x) => x.trim());
    if (parts.length >= 2 && parts.every((x) => IDENT.test(x))) {
      for (const x of parts) set.add(x);
    }
  }
  // ПЕРЕЧЕНЬ ПО СТРОКАМ: «имя — описание», по одному полю на строку.
  //
  // С 01.09 шейпер печатает инвентарь именно так: описания приходят тем же
  // ответом каталога, и выбрасывать их значит оставлять поля без подписи —
  // ровно то, из-за чего `disability_flg` уехал в запрос без комментария.
  // Разбор про этот формат не знал и видел ОДНО поле вместо всех: тот же
  // разъезд печатающей и читающей ноды, что 2026-08-31 прожил сутки под
  // видом молчания каталога. Здесь он стоил бы дороже — «поля нет в витрине»
  // там, где оно есть.
  //
  // Перечень ищется ПОДРЯД ИДУЩИМИ строками, а не по заголовку над ними.
  // Заголовок якорем не работает: между «ПОЛЯ ПО ИМЕНИ «x»: 0 из 10» и самим
  // списком шейпер ставит абзац прозы, и разбор от заголовка обрывался на
  // первой же русской строке. А привязка к тексту заголовка — это ещё один
  // контракт между двумя нодами, то есть ещё одно место для того же разъезда.
  //
  // Две подряд строки-идентификатора прозой не бывают, поэтому пара —
  // достаточный признак перечня, и лишнего он не наберёт: одиночное имя
  // разбирается ниже и только следом за заголовком про поля.
  {
    const ROW = /^([A-Za-z_][A-Za-z0-9_]*)(\s+[—–-]\s+\S.*)?$/;
    let run = [];
    const flush = () => {
      if (run.length >= 2) for (const x of run) set.add(x);
      run = [];
    };
    for (const raw of String(body || '').split('
')) {
      const row = raw.trim().match(ROW);
      if (row) run.push(row[1]);
      else flush();
    }
    flush();
  }

  // Витрина с ОДНИМ полем перечнем не выглядит: запятой в строке нет,
  // и разбор давал пустой набор — то есть гейт выгрузки получал ложное
  // «метаданных не пришло». Одиночное имя принимается ТОЛЬКО следом
  // за заголовком про поля, иначе в инвентарь полезет любое слово прозы.
  if (!set.size) {
    const lines = String(body || '').split('
').map((x) => x.trim());
    for (let i = 0; i < lines.length - 1; i++) {
      if (!/ПОЛ[ЕЙЯ]/i.test(lines[i])) continue;
      for (let j = i + 1; j < Math.min(i + 3, lines.length); j++) {
        if (lines[j] && IDENT.test(lines[j])) { set.add(lines[j]); break; }
      }
    }
  }
  return set;
}

// ЕДИНСТВЕННЫЙ РАЗБОР ОТВЕТА КАТАЛОГА — ЗДЕСЬ, И ЧИТАЮТ ЕГО ВСЕ.
//
// «Build lookups» и «Build materials» отвечали на один и тот же вопрос —
// дал ли каталог состав полей — КАЖДЫЙ СВОИМ разбором текста. Расхождение
// достижимо не «при следующем дрейфе», а прямо сейчас: `fieldsOf` требует
