if (out.form_domain && !domainCovered) {
  tasks.push('домен формы «' + out.form_domain + '» не встречается в таблице ' +
    '«Домены» kb/index.md — вопросы этой темы боту не адресуются ни на что');
}
// Тема формы «Нет доступа к отчету» — одна из четырёх рабочих, и ответ на неё
// в базе должен быть. Пока статью о заявке на доступ прочитать не удалось,
// это самый конкретный пробел, какой можно назвать: известно и что нужно,
// и где этому лежать.
if (/доступ/i.test(String(out.topic_kind || '')) &&
    !okArticles.some((p) => /routing/.test(p))) {
  tasks.push('обращение про доступ, а статью о заявке бот не прочитал → ' +
    'проверить kb/process/routing.md: файл добирается кодом по теме формы, ' +
    'и раз он не доехал — либо тема распозналась иначе, либо статью ' +
    'не удалось прочитать');
}
// КАТАЛОГ ОТВЕТИЛ — ЗАДАЧИ ДЛЯ БАЗЫ НЕТ, то же условие, что у уверенности.
//
// Прогон 01.09: понижение уже не выписывалось, а задача «в реестре нет строки
// под этот вопрос» ехала по-прежнему. Половина правила — хуже целого: джун
// видит высокую уверенность и рядом задачу завести статью, и не может понять,
// чего от него хотят. Выполнить её к тому же нельзя: статью про состав полей
// писать запрещено архитектурой, поля живут в каталоге.
if (mat.masters_only && !answeredByCatalog) {
  tasks.push('в реестре нет строки под этот вопрос: читались только мастера ' +
    'домена (' + okArticles.join(', ') + ')');
}
if (Array.isArray(mat.articles_failed) && mat.articles_failed.length) {
  tasks.push('реестр ссылается на файл, которого нет: ' +
    mat.articles_failed.join(', '));
}
if (Array.isArray(mat.articles_invented) && mat.articles_invented.length) {
  // Это НЕ пробел базы: такой строки в реестре нет вовсе, и править там
  // нечего. Раньше этот случай печатался как «реестр ссылается на файл,
  // которого нет» — джуна отправляли чинить несуществующую строку.
  tasks.push('роутер назвал путь, которого нет в реестре: ' +
    mat.articles_invented.join(', ') +
    ' — это промах роутера, а не пробел базы; править нечего, ' +
    'но если такая статья нужна — её и правда нет');
}
const gotCols = Array.isArray(mat.cols_from_data) ? mat.cols_from_data : [];
const colsTail = gotCols.length
  ? '. Состав полей при этом добран из данных, ответ по нему полный — ' +
    'не хватает только описаний полей'
  : '';
if (Array.isArray(mat.dd_bad_urn) && mat.dd_bad_urn.length) {
  // Каждый код — своё действие. Раньше печаталась одна строка про «404 или
  // 401», и на 5xx она отправляла править реестр, который не сломан.
  const byCode = Array.isArray(mat.dd_failed_http) ? mat.dd_failed_http : [];
  const say = (c) =>
    c === 404 ? 'URN в реестре неверный — настоящий ищется поиском по имени '
                + 'витрины (фаза G в «DD Recon»), правится одна строка kb/index.md'
    : c === 401 ? 'истёк Service Account каталога — обновить credential'
    : c >= 500 ? 'каталог отвечает ошибкой сервера: это не реестр и не доступ, '
                 + 'повторить позже, а если повторяется — писать владельцам DD'
    : c === 403 ? 'доступ к объекту запрещён — вопрос прав, а не реестра'
    : `каталог ответил кодом ${c}, что это значит — не знаем`;
  const lines = byCode.length
    ? byCode.map((x) => `${shortUrn(x.urn)}: HTTP ${x.status} — ${say(Number(x.status))}`)
    : [mat.dd_bad_urn.map(shortUrn).join(', ') +
       ': каталог ответил ошибкой, код не сохранился'];
  tasks.push('КАТАЛОГ ОТКАЗАЛ — ' + lines.join('; ') + colsTail);
}
if (Array.isArray(mat.dd_parse_failed) && mat.dd_parse_failed.length) {
  tasks.push('СБОЙ БОТА, не пробел базы: каталог прислал состав полей, ' +
    'а разбор его не увидел — ' + mat.dd_parse_failed.join(', ') +
    '. Формат перечня печатает «DD Lookup», а читает «Build materials», ' +
    'и разъехаться они могут молча. Чинить разбор в build_time_flows.py ' +
    '(fieldsOf), а не реестр и не доступ');
}
if (Array.isArray(mat.dd_no_columns) && mat.dd_no_columns.length) {
  // КАТАЛОГ ОТВЕТИЛ 200 И ПУСТОЙ СПИСОК КОЛОНОК — А ПОЧЕМУ, КОД НЕ ЗНАЕТ.
  //
  // Здесь стояло «колонок у витрины не заведено» — и это была ДОГАДКА,
  // записанная как факт. Владелец говорит, что витрина в каталоге описана
  // и колонки с описаниями у неё есть; фаза G подтвердила, что URN верный.
  // Значит пустой ответ может значить и другое: ключ связи `columns`
  // у этой системы называется иначе, или колонки висят на второй
  // регистрации той же таблицы (фаза G показала кандидатов `greenplum`
  // и `dlh` на одну витрину).
  //
  // Отличить их можно только запросом к каталогу — это фаза H в «DD Recon».
  // Пока не отличили, называем ФАКТ («пустой список»), а не причину:
  // придуманная причина отправляет чинить не то, и в этом проекте она уже
  // дважды отправляла.
  tasks.push('КАТАЛОГ ВЕРНУЛ ПУСТОЙ СПИСОК КОЛОНОК по витринам: ' +
    mat.dd_no_columns.map(shortUrn).join(', ') +
    ' — запрос прошёл, а полей в ответе ноль. Почему именно, по ответу ' +
    'не видно: либо ключ связи у этой системы другой, либо колонки висят ' +
    'на второй регистрации той же таблицы, либо их правда нет. ' +
    'Отвечает на это фаза H в «DD Recon» — она спрашивает каталог ' +
    'по обеим регистрациям сразу' + colsTail);
}
if (mat.registry_error) {
  // Не задача для базы, а поломка доступа — но читает этот блок тот же
  // человек, и увидеть отказ он должен в первый день.
  tasks.push('РЕЕСТР БАЗЫ ЗНАНИЙ НЕ ПРОЧИТАН: ' + mat.registry_error +
    ' — это поломка бота, а не пробел базы. Проверить, что kb/index.md ' +
    'лежит по этому пути в GitLab-проекте бота и доступен его Service Account');
}
if (mat.dd_never_ran) {
  // Это не задача для базы знаний, а поломка бота — но печатается здесь же,
  // потому что читает этот блок тот же человек, и увидеть отказ он должен
  // в первый день, а не через две недели по фидбеку.
  tasks.push('СБОЙ БОТА, не пробел базы: метаданные по ' +
    (Array.isArray(mat.dd_failed) ? mat.dd_failed.map(shortUrn).join(', ') : '') +
    ' не запрашивались — узел каталога не выполнился. Проверить в «Support ' +
    'Bot Core», что нода «Collect articles» включена: выключенная пропускает ' +
    'данные насквозь, и условие «Need DD» становится ложным всегда');
} else if (Array.isArray(mat.dd_missing) && mat.dd_missing.length) {
  // Не задача для базы, а поломка бота — как и dd_never_ran. Причина
  // называется первой по вероятности: узел каталога должен вызываться
  // ПО РАЗУ НА ОБЪЕКТ, а при вызове пачкой субворкфлоу разбирает первый
  // и молча возвращает один результат на сколько угодно запрошенных.
  tasks.push('СБОЙ БОТА, не пробел базы: объекты ' +
    mat.dd_missing.map(shortUrn).join(', ') + ' не доехали до каталога — ' +
    'узел вернул меньше объектов, чем запрошено. Проверить в «Support Bot ' +
    'Core» режим ноды «Call DD Lookup»: должно стоять «Run once for each ' +
    'item», иначе разбирается только первый объект');
} else if (Array.isArray(mat.dd_failed) && mat.dd_failed.length) {
  tasks.push('метаданные не получены: ' + mat.dd_failed.map(shortUrn).join(', ') +
    ' — проверить URN в реестре и срок жизни Service Account');
}
if (Array.isArray(plan.dropped) && plan.dropped.length) {
  tasks.push('по лимиту объёма не читались: ' + plan.dropped.join(', '));
}
out.kb_tasks = tasks;

return [{ json: out }];

const stage = (name) => {
  try {
    const items = $(name).all();
    return { ran: true, j: (items[0] && items[0].json) || {}, n: items.length };
  } catch (e) {
    // $() бросает у узла, который НЕ ВЫПОЛНЯЛСЯ. Это не ошибка, а сам ответ
    // на вопрос «что не отработало»: ветка не пошла, IF увёл мимо.
    return { ran: false, j: {}, n: 0 };
  }
};
const arr = (v) => (Array.isArray(v) ? v : []);
const list = (v) => (arr(v).length ? arr(v).join(', ') : '—');
const yn = (v) => (v ? 'да' : 'нет');
const cut = (v, n) => {
  const t = String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
  return !t ? '—' : (t.length > n ? t.slice(0, n) + '… (+' + (t.length - n) + ')' : t);
};

let text = '';
try {
  const trig = stage('When called by adapter');
  const reg  = stage('Decode registry');
  const plan = stage('Plan');
  const coll = stage('Collect articles');
  const mat  = stage('Build materials');
  const pa   = stage('Parse answer');
  const chk  = stage('Check result');
  const rev  = stage('Parse revised');
  const ddl  = stage('Call DD Lookup');
  const lk   = stage('Lookup result');
  const ask  = stage('Parse pairs');

  const P = plan.j, M = mat.j, A = pa.j, C = chk.j;
  const L = [];
  const h = (t) => { L.push(''); L.push('## ' + t); };
  const kv = (k, v) => L.push('- ' + k + ': ' + v);

  L.push('# Трассировка прогона ядра');
  L.push('');
  // Отпечаток СБОРЩИКА, а не промптов: правка Code-ноды меняет его, и по
  // отчёту сразу видно, та ли это сборка. Без него разбор упирается
  // в «а вы импортировали?» — круг, который уже был.
  kv('сборка ядра', 'e583faca');
  kv('вопрос', cut(trig.j.question, 300));
  kv('режим', (trig.j.mode || '—') + ' · тема формы: ' + cut(P.topic_kind_used || trig.j.topic_kind, 80));

  h('1. Роутер — что ОН выбрал сам');
  if (P.registry_error) kv('РЕЕСТР НЕ ПРОЧИТАН', String(P.registry_error));
  if (P.router_error) kv('ОШИБКА РОУТЕРА', String(P.router_error));
  kv('домены', list(P.domains));
  kv('статьи', list(P.router_articles));
  // ТОЛЬКО СВОИ URN РОУТЕРА. Поле `dd` в плане — итоговый список, в него
  // код дописывает инвентарь; печатать его в разделе «что выбрал ОН сам»
  // значит приписывать роутеру чужую работу. Ровно эта путаница и была
  // в отчёте 01.09: URN стоял в разделе роутера, хотя добрал его код.
  const byCode = arr(P.dd_added_by_code).map(String);
  const ownDd = arr(P.dd).map((d) => String((d && d.urn) || d))
    .filter((u) => !byCode.includes(u));
  kv('метаданные (URN)', ownDd.length ? ownDd.join(', ') : '—');
  kv('реплика без вопроса', yn(P.no_question));
  kv('РОУТЕР НЕ ДАЛ НИЧЕГО', yn(P.router_empty_plan));
  // Тема названа, статей нет: всё, что доедет автору, добрал код
  // по мастерам домена. Промах 02.09 был именно этой формы.
  kv('назвал ТЕМУ, но НИ ОДНОЙ СТАТЬИ', yn(P.router_domain_only));
  if (arr(P.articles_invented).length) kv('придумал путей', list(P.articles_invented));
  if (arr(P.articles_recovered).length) kv('путь восстановлен по реестру', list(P.articles_recovered));
  kv('сырой ответ роутера', cut(P.router_raw, 400));

  h('2. Что добрал КОД (роутер об этом не просил)');
  kv('мастера домена', list(P.added_masters));
  kv('витрина по умолчанию', list(P.added_default_mart));
  kv('плейбук выгрузки', list(P.added_export));
  kv('конвенции SQL', list(P.added_query));
  kv('активная численность', list(P.added_headcount));
  kv('словарь синонимов', list(P.added_synonyms));
  kv('рецепт юнита', list(P.added_unit));
  kv('ссылка на юнит', list(P.added_unit_link));
  kv('маршрутизация', list(P.added_access));
  kv('метаданные добраны кодом', list(P.dd_added_by_code));

  // РЕШЕНИЯ ГЕЙТОВ, А НЕ ТОЛЬКО ФАКТ ЗАПУСКА УЗЛА.
  //
  // Прогон 01.09: отчёт честно сказал «Call DD Lookup НЕ ЗАПУСКАЛСЯ», но
  // не сказал ПОЧЕМУ — а причина была в гейте, читавшем $json вместо плана.
  // Разбор упёрся ровно в этот зазор: видно, что узел не пошёл, и не видно,
  // какое условие его не пустило.
  h('3а. Гейты конвейера — что решил каждый');
  kv('статей в плане (Any articles)', arr(P.files).length);
  kv('объектов метаданных в плане (Need DD)', P.dd_count == null ? '—' : P.dd_count);
  if (arr(P.dd).length && !ddl.ran) {
    L.push('- ⚠️ МЕТАДАННЫЕ ЗАПЛАНИРОВАНЫ, А УЗЕЛ НЕ ПОШЁЛ — смотреть гейт «Need DD»');
  }
  kv('справочник юнита (Need lookup)', yn(stage('Run lookups').ran));
  kv('сверка значений (Need check)', yn(chk.ran));
  kv('доспрос (Need retry)', yn(ask.ran));

  h('3. Гейты режима — почему код добирал именно это');
  kv('выгрузка', yn(P.is_export));
  kv('просьба про запрос', yn(P.is_query_help));
  kv('вопрос про доступ', yn(P.is_access));
  kv('вопрос про подразделение', yn(P.is_unit_question));
  kv('ссылка на юнит', P.unit_link ? (P.unit_link_kind + ' ' + P.unit_link_id) : 'нет');

  h('4. Что РЕАЛЬНО доехало до автора');
  // Статьи и витрины — РАЗНОЕ, и подставлять одно вместо другого нельзя:
  // раньше «статей прочитано» падало на длину tables_read, и число совпадало
  // случайно. Инвентарь показан отдельной строкой: именно он отвечает
  // на «есть ли такое поле».
  kv('статей всего в материалах', arr(P.files).length);
  kv('из них выбрал роутер', arr(M.router_picked).length);
  kv('витрин прочитано', arr(P.tables_read).length);
  kv('инвентарь полей получен по',
    arr(M.tables).filter((t) => t && arr(t.fields).length).length + ' витринам');
  kv('только мастера, совпадений нет', yn(M.masters_only));
  kv('материалы непустые', yn(M.has_materials));
  // РАЗМЕР ВХОДА АВТОРА. Разбор 02.09: прогон шёл четыре минуты вместо
  // тридцати секунд, и первый же вопрос был «не мы ли раздули промпт».
  // Ответ пришлось собирать офлайн, потому что в трассе размера не было
  // вовсе — при том что `materials_len` давно считается для телеметрии.
  // Время узла видно в n8n, объём входа рядом с ним — здесь.
  if (M.materials_len != null) {
    kv('размер материалов',
       M.materials_len + ' символов ≈ ' +
       Math.round(M.materials_len / 2.7) + ' токенов (плюс статика промпта)');
  }
  if (arr(coll.j.articles_failed).length) kv('НЕ ПРОЧИТАЛОСЬ', list(coll.j.articles_failed));
  if (arr(P.dropped).length) kv('срезано потолком статей', list(P.dropped));
  if (arr(P.dd_dropped).length) kv('срезано потолком метаданных', list(P.dd_dropped));
  if (arr(M.tables_no_meta).length) kv('ВИТРИНА БЕЗ ИНВЕНТАРЯ ПОЛЕЙ', list(M.tables_no_meta));

  // ВСЕ УЗЛЫ ЯДРА, А НЕ ПЯТЬ ИЗБРАННЫХ.
  //
  // Прошлая версия перечисляла только листья: «Call DD Lookup не запускался»,
  // а какой именно узел до него оборвал цепочку — приходилось домысливать.
  // Сам «Split DD» в отчёт не попадал вовсе, и разбор 01.09 из-за этого ушёл
  // на две итерации починки не того места.
  //
  // Список имён вклеивает сборщик — он и так знает все узлы. Значит список
  // не разъедется: добавили узел в конвейер — он появился и в отчёте.
  //
  // ПУТЬ ПРОГОНА, А НЕ «ГДЕ ОБОРВАЛОСЬ». Ветки IF взаимоисключающие, и
  // невыполненный узел — чаще норма, чем поломка: назвать первый попавшийся
  // «местом обрыва» значило бы обвинять исправный узел.
  h('5. Узлы ядра — что отработало');
  const CHAIN = ["When called by adapter", "Get a file", "Decode registry", "Router", "Plan", "Split paths", "Read article", "Collect articles", "Any articles", "Need DD", "Split DD", "Call DD Lookup", "Build lookups", "Need lookup", "Run lookups", "Lookup result", "Build materials", "Author", "Parse answer", "Build check SQL", "Need check", "Need retry", "Ask pairs", "Parse pairs", "Retry check SQL", "Need check after ask", "Check values", "Check result", "Revise draft", "Parse revised", "Final answer"];
  const ranNames = [];
  for (const name of CHAIN) {
    const s2 = stage(name);
    if (s2.ran) ranNames.push(name);
    L.push('- ' + name + ': ' +
      (s2.ran ? ('отработал, элементов ' + s2.n) : 'НЕ ЗАПУСКАЛСЯ'));
  }
  L.push('');
  L.push('**Путь прогона:** ' + (ranNames.join(' → ') || 'ни один узел не отработал'));

  h('6. Сверка значений в Trino');
  if (!chk.ran) {
    kv('не выполнялась', 'проверять было нечего либо гейт не пустил');
  } else {
    kv('строк найдено', C.check_rows == null ? '—' : C.check_rows);
    kv('точных совпадений', C.check_exact == null ? '—' : C.check_exact);
    kv('поля', list(C.check_fields));
    if (C.check_failed) kv('ЗАПРОС УПАЛ', cut(C.check_failed, 300));
  }

  h('7. Ответ');
  kv('уверенность заявлена', A.confidence_claimed || A.confidence || '—');
  kv('уверенность действующая', A.confidence_key || '—');
  if (A.confidence_capped) kv('ПОНИЖЕНА КОДОМ', cut(A.confidence_capped_reason, 300));
  if (A.parse_error) kv('ОШИБКА РАЗБОРА ОТВЕТА', cut(A.parse_error, 300));
  if (A.gaps) kv('чего не хватило', cut(A.gaps, 300));
  kv('второй проход', yn(rev.ran));

  // САМОЕ ЧИТАЕМОЕ — В КОНЕЦ. Всё, что выше, это данные; здесь список того,
  // что пошло не так, одним взглядом. Пустой список — тоже ответ.
  // Поля, закрытые каталогом: по ним видно, ПОЧЕМУ понижения за пустой
  // реестр не случилось. Без строки разница между «уверен» и «правило
  // промолчало» по отчёту неразличима.
  if (arr(A.catalog_only_fields).length) {
    kv('закрыто каталогом (в статьях этих полей нет)',
       list(A.catalog_only_fields));
  }

  // Чувствительность: сколько полей каталог назвал закрытыми и какие из них
  // остались без замка. Без этих строк промах 01.09 по отчёту не виден вовсе.
  kv('закрытых полей по каталогу', A.sens_fields == null ? '—' : A.sens_fields);
  if (arr(A.sens_unmarked_fields).length) {
    kv('⚠️ ЗАКРЫТО КАТАЛОГОМ, А ЗАМКА НЕТ', list(A.sens_unmarked_fields));
  }

  h('8. ИТОГ: что не отработало');
  const bad = [];
  if (P.registry_error) bad.push('реестр не прочитан');
  if (P.router_error) bad.push('роутер ответил ошибкой');
  if (P.router_empty_plan) bad.push('роутер не дал ни домена, ни статьи');
  if (arr(P.articles_invented).length) bad.push('роутер придумал путь к статье');
  if (arr(coll.j.articles_failed).length) bad.push('статья не прочиталась');
  if (arr(P.dropped).length) bad.push('статьи срезаны потолком');
  if (arr(P.dd_dropped).length) bad.push('метаданные срезаны потолком');
  if (arr(M.tables_no_meta).length) bad.push('витрина прочитана без инвентаря полей');
  if (!M.has_materials) bad.push('материалы пустые — автору читать было нечего');
  if (C.check_failed) bad.push('проверочный запрос упал');
  if (A.parse_error) bad.push('ответ автора не разобрался');
  if (A.confidence_capped) bad.push('уверенность понижена кодом');
  if (arr(A.sens_unmarked_fields).length) {
    bad.push('закрытое каталогом поле названо без замка: ' +
             arr(A.sens_unmarked_fields).join(', '));
  }
  L.push(bad.length ? bad.map((b) => '- ' + b).join('\n') : '- всё отработало штатно');

  text = L.join('\n');
} catch (e) {
  // Отчёт не собрался — это не повод ронять ответ на обращение.
  text = 'Трассировка не собралась: ' + String(e && e.message ? e.message : e);
}

// Вход проходит НАСКВОЗЬ: «Final answer» стоит следом и читает свои узлы
// по имени, но подменять ему вход трассировкой всё равно нельзя.
return [{ json: { ...$json, trace: text } }];

// ЧЕРНОВИК — ЭТО MARKDOWN, А НЕ ЧИСТЫЙ SQL, и пара живёт не только внутри
// блока кода. Живой прогон 2026-08-28: автор не стал ставить значения
// в запрос, а вынес их списком в текст —
//     - `emp_specialization_desc` = 'GO разработчик'
// — то есть сделал ровно то, что от него и требуется, и проверка всё равно
// не запустилась: имя поля обёрнуто в обратные кавычки, а прежняя регулярка
// допускала между именем и оператором только скобку и пробелы.
//
// Поэтому разметка снимается ДО разбора, а не описывается в регулярке:
// список того, чем модель может обрамить имя поля, открыт, и гнаться за ним
// регуляркой значит проигрывать ему каждый раз заново.
// ПОДЧЁРКИВАНИЕ НЕ СНИМАЕТСЯ. Оно и разметка курсива, и часть КАЖДОГО имени
// поля: `emp_specialization_desc` после общей чистки стал бы тремя словами,
// и в отбор ушло бы `desc` — «нет в инвентаре».
// Кавычки у значения принимаются любые: в SQL одинарные, в прозе часто
// ёлочки или двойные. Пропустить пару из-за кавычки значит не проверить
// значение, которое автор назвал прямым текстом.
const PAIR_LIT = "'(?:[^']|'')*'|\"[^\"]*\"|«[^»]*»";
function draftPairs(text) {
  const src = String(text || '').replace(/[`*~]+/g, ' ');
  const re = new RegExp(
    '([a-z_][a-z0-9_]*)\\s*\\)?\\s*(?:=|<>|!=|i?like|in)\\s*\\(?\\s*' +
    '((?:' + PAIR_LIT + ')(?:\\s*,\\s*(?:' + PAIR_LIT + '))*)', 'gi');
  const unq = (v) => v.slice(1, -1).replace(/''/g, "'");
  const out = [];
  let m;
  while ((m = re.exec(src)) !== null) {
    // Список IN разбирается целиком: проверить первое значение и промолчать
    // про остальные значит назвать проверенным то, что не проверяли.
    for (const lit of m[2].match(new RegExp(PAIR_LIT, 'g')) || []) {
      out.push({ field: m[1].toLowerCase(), value: unq(lit) });
    }
  }
  return out;
}

// Ответ второго прохода, если он был, иначе первого. Обе ветви
// взаимоисключающие, поэтому узел выполняется один раз.
let out = null;
let revised = false;
try {
  const r = $('Parse revised').first().json;
  if (r && r.draft !== undefined) { out = { ...r }; revised = true; }
} catch (e) { /* цикл не понадобился — нормальный путь */ }

const first = $('Parse answer').first().json;
if (!out) out = { ...first };

// ВТОРОЙ ПРОХОД НЕ ИМЕЕТ ПРАВА ТЕРЯТЬ ТО, ЧТО БЫЛО В ПЕРВОМ.
//
// Живой прогон 2026-08-31, выгрузка про детей сотрудников. Проверка значений
// отработала, черновик переписался — и ТЗ ДЛЯ АНАЛИТИКА исчезло целиком:
// REVISE_PROMPT перечислял четыре блока и про ТЗ не говорил вовсе, так что
// модель его просто не вывела. В логе осталось «нет блока ТЗ ДЛЯ АНАЛИТИКА»
// как ошибка разбора — то есть по виду это выглядело как сбой формата,
// а на деле блок и не запрашивали.
//
// Промпт теперь ТЗ требует, но словесное требование модель роняет —
// прецедентов шесть. Поэтому код ДОБИРАЕТ потерянное из первого прохода
// и говорит об этом: значения фильтров в таком ТЗ остались непроверенными,
// и молча выдать его за правленое нельзя.
if (revised) {
  const carried = [];
  for (const k of ['tech_spec', 'sources', 'gaps']) {
    if (!String(out[k] || '').trim() && String(first[k] || '').trim()) {
      out[k] = first[k];
      carried.push(k);
    }
  }
  out.revise_carried = carried;
  // Формат сломан целиком: во втором проходе не нашлось НИ ОДНОГО ярлыка,
  // и черновиком стал весь сырой текст вместе со служебными рассуждениями.
  // Тогда правленый черновик хуже исходного — берём первый, он разобран.
  if (/не найдено ни одного блока/.test(String(out.parse_error || '')) &&
      String(first.draft || '').trim()) {
    out.draft = first.draft;
    out.revise_dropped = true;
    out.parse_error = 'второй проход вернул текст без блоков — оставлен ' +
                      'черновик первого прохода, значения в нём НЕ проверены';
  } else {
    out.revise_dropped = false;
  }
} else {
  out.revise_carried = [];
  out.revise_dropped = false;
}
// Присваивается отдельной строкой, а не внутри спреда: поля ядра ищутся
// по `out.<имя> =`, и спрятанное в спреде поле проверка не увидит — ровно
// так `experts_invented` и `draft_own_tools` однажды проскочили мимо теста.
out.revised = revised;

// Факты о самой проверке — в телеметрию и в служебный блок джуну: по ним
// видно, спрашивал ли автор значения и что вернули данные.
let checkReason = '';
out.check_retried = false;
try {
  // Тот же порядок, что в «Check result»: сборщик после доспроса главнее.
  let plan;
  try {
    plan = $('Retry check SQL').first().json;
    out.check_retried = true;
  } catch (e) { plan = $('Build check SQL').first().json; }
  out.check_asked = (plan.check_pairs || []).length;
  out.check_skipped = (plan.check_skipped || []).length;
  checkReason = String(plan.check_reason || '');
} catch (e) { out.check_asked = 0; out.check_skipped = 0; }
let checkRest = {};
try {
  const res = $('Check result').first().json;
  out.check_rows = res.check_rows || 0;
  out.check_failed = res.check_failed || '';
  out.check_exact = res.check_exact || 0;
  out.check_rows_capped = res.check_rows_capped || 0;
  // Список проверенных «витрина.поле»: нужен джуну, чтобы строка про словарь
  // значений называла, ПО ЧЕМУ он поднят. Число без этого не читается.
  out.check_fields = Array.isArray(res.check_fields) ? res.check_fields : [];
  out.check_exact_values = Array.isArray(res.check_exact_values)
    ? res.check_exact_values : [];
  checkRest = res.check_rest || {};
} catch (e) {
  out.check_rows = 0; out.check_failed = ''; out.check_exact = 0; out.check_fields = [];
  out.check_rows_capped = 0;
}

// ПОДМЕНА: В ФИЛЬТРЕ ЗНАЧЕНИЕ, КОТОРОГО ЗАКАЗЧИК НЕ НАЗЫВАЛ.
//
// Живой прогон 2026-08-31, «сколько сотрудников по покраске HQ и BigOps».
// Ни «HQ», ни «BigOps» не совпали ни с одним значением
// lvl3_mapped_management_unit_nm — и автор подставил в фильтр три значения
// из перечня прочих: «Финансы», «Human Capital», «Технологии, Безопасность,
// Операции», расписав, какие из них штабные функции. Запрос выполнился,
// вернул правдоподобные и неверные цифры, а проверка значений при этом
// отчиталась успехом: строки-то пришли.
//
// Формулировки в блоке и в промпте поправлены, но словесные правила модель
// роняет — прецедентов четыре (мастера домена, лимит итераций, согласование
// ИБ, select distinct). Поэтому код МЕРИТ: значение из группы «прочие»
// (то есть ни точное совпадение, ни похожее) в итоговом фильтре — это
// значение, которого заказчик не называл ни разу.
//
// Проверка узкая намеренно, как experts_invented: сверяем только с перечнем,
// который сами же и показали. Придуманное с нуля значение она не поймает —
// померить это нечем, — зато ложных тревог у неё нет.
{
  const subs = [];
  const fin = String(out.draft || '') + '\n' + String(out.tech_spec || '');
  for (const pr of draftPairs(fin)) {
    const rest = checkRest[pr.field];
    if (!Array.isArray(rest)) continue;
    const hit = rest.find((v) => v.toLowerCase() === pr.value.toLowerCase());
    if (hit !== undefined && !subs.some((x) => x.field === pr.field && x.value === hit)) {
      subs.push({ field: pr.field, value: hit });
    }
  }
  out.check_substituted = subs;
}

// ЧУЖОЙ ИДЕНТИФИКАТОР В ОТВЕТЕ.
//
// Живой прогон 2026-08-31: ключ юнита пришёл БЕЗ дефисов, идентификатором
// не опознался, вместо точечного запроса собрался словарь по всему полю —
// и автор предложил заказчику девять чужих хешей: «в поле есть также
// 6693daa4…, 86004218… — если нужны они, скажите, добавлю в фильтр».
// Выбрать из хешей нельзя ни автору, ни заказчику, а каждый из них —
// чужое подразделение.
//
// Проверка узкая и без ложных тревог по построению: считаются только
// идентификаторы, которых заказчик не называл и данные не подтверждали.
// Свой ключ из ссылки, разрешённый кодом ключ юнита и подтверждённые
// значения исключены.
{
  const own = new Set();
  const add = (v) => {
    const k = String(v || '').toLowerCase().replace(/-/g, '');
    if (k) own.add(k);
  };
  try {
    const m = $('Build materials').first().json;
    add(m.unit_link_id);
    add(m.unit_rk);
  } catch (e) { /* ветки юнита в прогоне не было */ }
  for (const v of (out.check_exact_values || [])) add(v);
  const q = String(first.question || '').toLowerCase().replace(/-/g, '');
  const fin = String(out.draft || '') + '\n' + String(out.tech_spec || '');
  const seen = new Set();
  for (const m of (fin.match(/[0-9a-f-]{16,}/gi) || [])) {
    const k = m.toLowerCase().replace(/-/g, '');
    if (!/^[0-9a-f]{16,}$/.test(k)) continue;   // это не хеш, а что-то иное
    if (own.has(k) || q.includes(k) || seen.has(k)) continue;
    seen.add(k);
  }
  out.draft_foreign_ids = [...seen].slice(0, 5);
}

// НЕПОДПИСАННЫЙ КЛЮЧ В ЗАПРОСЕ.
//
// Фильтр по хешу человеком не читается: аналитик не может проверить, тот ли
// это юнит, не сходив в справочник сам, а через месяц по нему никто
// не поймёт, что выгружалось. Название у нас на руках — значит оно обязано
// стоять комментарием рядом.
//
// Проверка узкая и без ложных тревог по построению: ищется РОВНО тот ключ,
// который код сам разрешил, и рядом с ним — его же название. Придуманные
// или чужие ключи ловит draft_foreign_ids, это другая проверка.
{
  let rk = '';
  let nm = '';
  try {
    const m = $('Build materials').first().json;
    rk = String(m.unit_rk || '');
    nm = String(m.unit_nm || '');
  } catch (e) { /* ветки юнита не было */ }
  const spec = String(out.tech_spec || '') + '\n' + String(out.draft || '');
  let missing = false;
  if (rk && nm && spec.includes(rk)) {
    // Подпись ищется в тех же строках, где стоит ключ: комментарий этажом
    // выше или в соседнем разделе фильтр не подписывает.
    missing = !spec.split('\n')
      .filter((l) => l.includes(rk))
      .some((l) => l.toLowerCase().includes(nm.toLowerCase()));
  }
  out.draft_key_unlabeled = missing ? [rk] : [];
}

// ПЕРЕСПРОС ПРО ДАТУ, КОТОРОЙ ЗАКАЗЧИК НЕ НАЗЫВАЛ.
//
// Чаще всего человеку нужно состояние НА СЕЙЧАС: не назвал ни даты,
// ни периода — значит актуальный срез, и это НЕ пробел запроса.
// Уточняющий вопрос здесь стоит заказчику лишнего круга ожидания ради
// ответа, который был очевиден с самого начала.
//
// Проверка узкая: вопрос про дату считается лишним ТОЛЬКО когда сам
// заказчик о времени не писал. Написал «за квартал», «на 1 июля»,
// «в динамике» — уточнение уместно, и тревоги нет.
//
// ЗАКРЫТЫЙ ПЕРЕЧЕНЬ ФРАЗ ЗДЕСЬ НЕ РАБОТАЕТ, И ЭТО ИЗМЕРЕНО.
//
// Прежняя версия перечисляла шесть формулировок вопроса — и была
// частично МЁРТВОЙ против образца ИЗ СОБСТВЕННОГО промпта бота:
// «актуальный срез или срез за период?» стоит в `prompts/export.md`
// как пример правильной формы вопроса, а регулярка требовала
// «актуальный срез ИЛИ ЗА ПЕРИОД» и на нём молчала. То есть детектор
// не ловил ровно ту фразу, которой мы сами модель и учим.
//
// Гнаться за формулировками бессмысленно — их список открыт, ровно как
// список форм разметки в разборе пар «поле = значение». Поэтому признак
// СТРУКТУРНЫЙ: в одном предложении стоят ФОРМА ВОПРОСА и КОРЕНЬ ВРЕМЕНИ.
// Оба перечня — про язык, а не про случай: корней времени в русском
// конечное число, форм вопроса тоже.
//
// Требование «в ОДНОМ предложении» существенно: черновик, где рядом
// стоят «данные на текущую дату» и «нужны ли отклонённые?», это верный
// черновик, и складывать признаки по всему тексту значило бы получить
// ложную тревогу на нём.
{
  // Текст, который написал ЧЕЛОВЕК: `question_own` из `Plan`. По сырому
  // вопросу проверка работать не может — в форме есть подпись «Срок:»
  // и вариант списка «(… возраст, master ID …)», и оба содержат слова
  // про время, которых заказчик не писал. Фолбэк на сырой вопрос оставлен
  // на случай старого `Plan`: он даёт больше молчания, а не больше тревог.
  const planJson = (() => { try { return $('Plan').first().json; } catch (e) { return {}; } })();
  const q = String(planJson.question_own || first.question || '').toLowerCase();
  // Литерал регулярки в JS не переносится на новую строку — собираем
  // из кусков конструктором. Кириллические хвосты классом [а-яё],
  // без \w и \b: правило проекта, три тихих промаха на этом уже было.
  //
  // Перечень КОРНЕЙ, а не фраз: «за прошлый месяц» и «за последние
  // полгода» прежнюю версию проходили молча — она знала «за месяц»
  // и «полугод», но не «прошлый месяц» и не «полгода». Направление
  // послабления выбрано по цене промаха: лишний корень тут гасит тревогу
  // (джун не увидит строку про лишний вопрос), недостающий — зажигает её
  // на верном черновике, где заказчик период НАЗВАЛ. Ложная тревога хуже.
  const TIME_PARTS = [
    'январ', 'феврал', 'март', 'апрел', 'ма[йя]', 'июн', 'июл', 'август',
    'сентябр', 'октябр', 'ноябр', 'декабр',
    'квартал', 'полугод', 'полгода', 'месяц', 'недел', 'сутк',
    '(^|[^а-яё])год', 'года', 'году', 'годов',
    'период', 'динамик', 'истори', 'интервал', 'диапазон',
    'дат[аеуыо]', 'датам', 'врем[яеен]',
    'помесячн', 'понедельн', 'поквартальн', 'ежемесячн', 'еженедельн',
    'ежегодн', 'ежедневн', 'на начало', 'на конец', 'по состоянию',
    'вчера', 'нараста',
    '\\d{1,2}\\.\\d{2}', '\\d{4}-\\d{2}', '\\d{4}\\s*г',
  ];
  // «Сейчас», «сегодня», «актуальный» — это НЕ названный период, это
  // умолчание, произнесённое вслух. В вопросе бота они признак времени
  // («актуальный срез или срез за период?» — вопрос про дату), а в словах
  // заказчика тревогу гасить не должны: «сколько сейчас сотрудников» —
  // самый частый вопрос канала, и переспрашивать про дату на нём как раз
  // и есть тот лишний круг, ради которого проверка заведена.
  const NOW_PARTS = ['сегодня', 'сейчас', 'текущ', 'актуальн', 'срез'];
  const TIME_ROOT = new RegExp(TIME_PARTS.concat(NOW_PARTS).join('|'), 'i');
  const SAID_TIME = new RegExp(TIME_PARTS.join('|'), 'i');
  // Форма вопроса. Вопросительный знак покрывает основную массу, но
  // не всё: «уточните период» — просьба без знака, и это тот же лишний
  // круг ожидания для заказчика.
  const ASK_FORM = new RegExp([
    '\\?', 'уточни', 'подскаж', 'сообщ', 'напиши', 'нужн[а-яё]* ли',
    'какой', 'какая', 'како[ей]', 'каку[юя]', 'нужен ли',
  ].join('|'), 'i');
  const text = String(out.draft || '');
  // Границы предложения: перевод строки и терминаторы. Знак вопроса
  // остаётся в куске, иначе ASK_FORM его не увидит.
  const sentences = text
    .replace(/([?!.])\s/g, '$1\n')
    .split('\n')
    .map((l) => l.trim())
    .filter(Boolean);
  const hits = sentences.filter((l) => ASK_FORM.test(l) && TIME_ROOT.test(l));
  out.draft_asks_date = !SAID_TIME.test(q) && hits.length > 0;
}

// ПОНИЖЕНИЕ, КОГДА ЗНАЧЕНИЕ В ЧЕРНОВИКЕ ОСТАЛОСЬ НЕПОДТВЕРЖДЁННЫМ.
//
// Пары код добывает из самого черновика, то есть проверка запускается ровно
// там, где ответ содержит утверждение о данных: «специализация записана
// вот так». Если данные это утверждение не подтвердили — запрос отказал или
// строк не вернул, — то «высокая уверенность» относится к значению, которого
// никто не видел. Заказчик скопирует фильтр и получит ноль строк.
//
// Понижаем до средней, а не до «нет ответа»: поле названо верно, статья
// прочитана, ответ по существу собран — не подтверждено одно звено.
// Повышений тут нет и быть не может: подтверждённое значение — это норма,
// а не заслуга.
// ПРОТИВОРЕЧИЕ: АВТОР ГОВОРИТ, ЧТО ЗНАЧЕНИЕ НЕ ПРОВЕРЕНО, А ПРОВЕРКА
// НЕ ЗАПУСКАЛАСЬ. Это самый надёжный признак промаха разбора пар.
//
// Пары код достаёт из свободного текста модели, и каждый промах до сих пор
// был ТИХИМ: сначала гейтом был блок автора (2026-08-28, «автор не просил»),
// потом имя поля в обратных кавычках («в черновике нет фильтров»). Оба раза
// в логе стояла честная причина, и оба раза она читалась как «проверять было
// нечего». Гнаться регуляркой за очередной формой разметки — проигрышная
// гонка; вместо этого ловим само противоречие.
//
// Автор в «Чего не хватило» прямо пишет, что написание значения неизвестно,
// а `check_asked` при этом ноль — значит разбор промахнулся, и джун обязан
// это видеть вместе с причиной, которую записал код.
{
  const said = String(out.gaps || '') + '\n' + String(out.draft || '');
  const NEEDS = /select\s+distinct|не\s+провер[а-яё]+|неизвестн[а-яё]*|уточни[а-яё]+\s+(?:точное\s+)?значени|подтверди[а-яё]+\s+(?:точное\s+)?(?:значени|написани)/i;
  // После доспроса это уже не «разбор промахнулся», а «автор посмотрел
  // и пар не назвал» — разные диагнозы, и чинятся они в разных местах.
  out.check_missed = out.check_asked === 0 && NEEDS.test(said);
  out.check_reason = checkReason;
}

// УСТАРЕВШАЯ ОГОВОРКА: ЧЕРНОВИК ПРОСИТ ПРОВЕРИТЬ ТО, ЧТО УЖЕ ПРОВЕРЕНО.
//
// Правило «не пиши „уточните через select distinct“» стоит в промпте автора
// и всё равно роняется — живой прогон 2026-08-28 дал эту фразу трижды
// в одном ответе. Промпт не удержал, значит мерит код.
//
// Условие узкое намеренно: оговорка считается устаревшей ТОЛЬКО когда
// проверка реально подтвердила значения. Не проверяли или проверка
// отказала — совет коллеге уточнить самому остаётся верным, и тревожить
// джуна незачем: строка, которая горит на верном черновике, обесценивает
// и себя, и соседние.
{
  const t = String(out.draft || '') + '\n' + String(out.tech_spec || '');
  const CAVEAT = /select\s+distinct|уточни[а-яё]*\s+(?:точное\s+)?значени|подтверди[а-яё]*\s+(?:точное\s+)?(?:значени|написани)/i;
  out.draft_stale_caveat = out.check_rows > 0 && CAVEAT.test(t);
}

if (out.check_asked > 0 && (out.check_failed || !out.check_rows)) {
  const why = out.check_failed
    ? 'значение фильтра проверить не удалось: ' + out.check_failed
    : 'значение фильтра в данных не подтвердилось — строк не вернулось';
  const RANK = { none: 0, medium: 1, high: 2 };
  if (out.confidence_key !== 'unknown' && RANK.medium < (RANK[out.confidence_key] ?? 2)) {
    out.confidence_key = 'medium';
  }
  out.confidence_capped_reason = [out.confidence_capped_reason, why]
    .filter(Boolean).join('; ');
  out.confidence_capped = out.confidence_key !== out.confidence_claimed;
}

// Подмена значения понижает до средней, и это не то же самое, что «значение
// не подтвердилось». Там данные промолчали, здесь они ОТВЕТИЛИ — и ответ
// был «такого значения нет», а в фильтр всё равно уехало чужое. Основание
// под цифрой тут не неполное, а подменённое, и джун обязан это увидеть.
// До «нет ответа» не понижаем: поле и статья могут быть верными, неверен
// один шаг — но шаг решающий.
if (Array.isArray(out.check_substituted) && out.check_substituted.length) {
  const RANK2 = { none: 0, medium: 1, high: 2 };
  if (out.confidence_key !== 'unknown' && RANK2.medium < (RANK2[out.confidence_key] ?? 2)) {
    out.confidence_key = 'medium';
  }
  out.confidence_capped_reason = [
    out.confidence_capped_reason,
    'в фильтре значение, которого заказчик не называл: ' +
      out.check_substituted.map((x) => x.field + ' = «' + x.value + '»').join(', '),
  ].filter(Boolean).join('; ');
  out.confidence_capped = out.confidence_key !== out.confidence_claimed;
}

return [{ json: out }];
